private ActivityResultLauncher<String> pickRoomPhoto=registerForActivityResult(new ActivityResultContracts.GetContent(),uri->{if(uri!=null){pickedRoomPhotoUri=uri;try{InputStream is=getContentResolver().openInputStream(uri);Bitmap bmp=BitmapFactory.decodeStream(is);if(is!=null)is.close();if(bmp!=null){ByteArrayOutputStream baos=new ByteArrayOutputStream();Bitmap scaled=Bitmap.createScaledBitmap(bmp,400,400,true);scaled.compress(Bitmap.CompressFormat.JPEG,70,baos);pickedRoomPhotoBase64=Base64.encodeToString(baos.toByteArray(),Base64.DEFAULT);}}catch(Exception e){pickedRoomPhotoBase64=null;}if(dialogRoomPhoto!=null)Glide.with(this).load(uri).circleCrop().into(dialogRoomPhoto);}});
private String getGiftEmoji(String name){if(name==null)return "🎁";switch(name){case "Rose":return "🌹";case "Heart":return "❤️";case "Cake":return "🎂";case "Diamond":return "💎";case "Car":return "🚗";case "Crown":return "👑";case "Plane":return "✈️";case "Castle":return "🏰";default:return "🎁";}}
private long readWalletFromSnap(DataSnapshot snap){long m=0;m=Math.max(m,getLongVal(snap,"coins"));m=Math.max(m,getLongVal(snap,"coinBalance"));m=Math.max(m,getLongVal(snap,"walletCoins"));m=Math.max(m,getLongVal(snap,"sendingCoins"));m=Math.max(m,getLongVal(snap,"totalCoins"));return m;}
private long getLongVal(DataSnapshot snap,String k){try{Object v=snap.child(k).getValue();if(v==null)return 0;if(v instanceof Number)return ((Number)v).longValue();return Long.parseLong(String.valueOf(v).replace(",","").trim());}catch(Exception e){return 0;}}
private void refreshMyWalletUI(){myWalletBalance=Math.max(myWalletUidNode,myWalletProfileNode);if(currentGiftBalanceView!=null)currentGiftBalanceView.setText("💰 "+myWalletBalance+" Coins");}
