private void startWalletListener(){try{FirebaseUser fu=FirebaseAuth.getInstance().getCurrentUser();if(fu!=null)myFirebaseUid=fu.getUid();}catch(Exception ignored){}if((myFirebaseUid==null||myFirebaseUid.isEmpty())&&prefs!=null)myFirebaseUid=prefs.getString("FIREBASE_UID","");if(myFirebaseUid==null)myFirebaseUid="";String pid=myId==null?"":myId.trim();if(!myFirebaseUid.isEmpty())myWalletRefUid=FirebaseDatabase.getInstance().getReference("users").child(myFirebaseUid);if(!pid.isEmpty()&&!pid.equals(myFirebaseUid))myWalletRefProfile=FirebaseDatabase.getInstance().getReference("users").child(pid);if(myWalletRefUid==null&&myWalletRefProfile!=null){myWalletRefUid=myWalletRefProfile;myWalletRefProfile=null;}if(myWalletRefUid!=null){myWalletListenerUid=new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){myWalletUidNode=readWalletFromSnap(s);refreshMyWalletUI();}@Override public void onCancelled(@NonNull DatabaseError e){}};myWalletRefUid.addValueEventListener(myWalletListenerUid);}if(myWalletRefProfile!=null){myWalletListenerProfile=new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){myWalletProfileNode=readWalletFromSnap(s);refreshMyWalletUI();}@Override public void onCancelled(@NonNull DatabaseError e){}};myWalletRefProfile.addValueEventListener(myWalletListenerProfile);}}
private void resolveUserKeyByProfileId(String profileId,java.util.function.Consumer<String> cb){if(profileId==null||profileId.trim().isEmpty()){cb.accept("");return;}String pid=profileId.trim();FirebaseDatabase.getInstance().getReference("users").child(pid).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){if(s.exists()){cb.accept(pid);return;}queryUserKey(pid,"my9DigitId",cb);}@Override public void onCancelled(@NonNull DatabaseError e){queryUserKey(pid,"my9DigitId",cb);}});}
private void queryUserKey(String pid,String field,java.util.function.Consumer<String> cb){FirebaseDatabase.getInstance().getReference("users").orderByChild(field).equalTo(pid).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s){if(s.exists()){for(DataSnapshot c:s.getChildren()){cb.accept(c.getKey());return;}}if("my9DigitId".equals(field))queryUserKey(pid,"profileId",cb);else if("profileId".equals(field))queryUserKey(pid,"PROFILE_ID",cb);else if("PROFILE_ID".equals(field))queryUserKey(pid,"id",cb);else cb.accept(pid);}@Override public void onCancelled(@NonNull DatabaseError e){cb.accept(pid);}});}
