private int[] getVipBgColors(int lvl){switch(lvl){case 1:return new int[]{0xFF3A0A4A,0xFF1A0B2E};case 2:return new int[]{0xFFE8E8E8,0xFF9E9E9E};case 3:return new int[]{0xFFFF6D00,0xFF8B0000};case 4:return new int[]{0xFFFF9800,0xFFD32F2F};case 5:return new int[]{0xFF00BCD4,0xFF1A0B2E};case 6:return new int[]{0xFFFFD700,0xFFFF9800};case 7:return new int[]{0xFF7B1FA2,0xFF1A0B2E};case 8:return new int[]{0xFF9C27B0,0xFF4A148C};default:return new int[]{0xFF1B1035,0xFF0A0518};}}
private void fetchVipForUser(String targetId,java.util.function.Consumer<Integer> cb){FirebaseDatabase.getInstance().getReference("vip_assignments").child(targetId).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){if(snap.exists()&&snap.child("vipLevel").getValue()!=null){try{int v=Integer.parseInt(String.valueOf(snap.child("vipLevel").getValue()));long exp=0;try{exp=Long.parseLong(String.valueOf(snap.child("expireAt").getValue()));}catch(Exception ignored){}if(exp==0){try{exp=Long.parseLong(String.valueOf(snap.child("expireTs").getValue()));}catch(Exception ignored){}}if(exp>0&&System.currentTimeMillis()>exp)v=0;cb.accept(v);return;}catch(Exception ignored){}}FirebaseDatabase.getInstance().getReference("users").child(targetId).child("vipLevel").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot s2){int v=0;try{if(s2.exists()&&s2.getValue()!=null)v=Integer.parseInt(String.valueOf(s2.getValue()));}catch(Exception ignored){}cb.accept(v);}@Override public void onCancelled(@NonNull DatabaseError e){cb.accept(0);}});}@Override public void onCancelled(@NonNull DatabaseError e){cb.accept(0);}});}
private void listenGiftEffects(){if(giftEffectListener!=null&&giftEffectQuery!=null){try{giftEffectQuery.removeEventListener(giftEffectListener);}catch(Exception ignored){}}giftEffectQuery=activeRoomRef.child("gift_effects").orderByChild("time").startAt(joinTime);giftEffectListener=new ChildEventListener(){@Override public void onChildAdded(@NonNull DataSnapshot snap,String p){if(snap==null||!snap.exists())return;String key=snap.getKey();if(key!=null&&seenGiftEffectIds.contains(key))return;if(key!=null)seenGiftEffectIds.add(key);Long t=snap.child("time").getValue(Long.class);if(t!=null&&t<joinTime-2000)return;String sName=snap.child("senderName").getValue(String.class);String rName=snap.child("targetName").getValue(String.class);String rId=snap.child("targetId").getValue(String.class);String gName=snap.child("giftName").getValue(String.class);Long cnt=snap.child("giftCount").getValue(Long.class);String sPhoto=snap.child("senderPhoto").getValue(String.class);String rPhoto=snap.child("targetPhoto").getValue(String.class);showGiftFlyingAnimation(sName==null?"User":sName,rName==null?"User":rName,rId==null?"":rId,gName==null?"Rose":gName,cnt==null?1:cnt.intValue(),sPhoto==null?"":sPhoto,rPhoto==null?"":rPhoto);}@Override public void onChildChanged(@NonNull DataSnapshot s,String p){}@Override public void onChildRemoved(@NonNull DataSnapshot s){}@Override public void onChildMoved(@NonNull DataSnapshot s,String p){}@Override public void onCancelled(@NonNull DatabaseError e){}};giftEffectQuery.addChildEventListener(giftEffectListener);}
private void showGiftFlyingAnimation(String sName,String rName,String rId,String gName,int count,String sPhoto,String rPhoto){try{android.widget.FrameLayout decor=(android.widget.FrameLayout)getWindow().getDecorView();android.widget.FrameLayout overlay=new android.widget.FrameLayout(this);overlay.setLayoutParams(new android.widget.FrameLayout.LayoutParams(android.widget.FrameLayout.LayoutParams.MATCH_PARENT, android.widget.FrameLayout.LayoutParams.MATCH_PARENT));overlay.setClickable(false);decor.addView(overlay);int targetSeatIndex=-1;for(int i=0;i<10;i++){ if(rId!=null && rId.equals(seatUserId.get("seat_"+i))){ targetSeatIndex=i; break; } }View targetView = targetSeatIndex!=-1 ? seatViews[targetSeatIndex] : null;android.widget.LinearLayout box=new android.widget.LinearLayout(this);box.setOrientation(android.widget.LinearLayout.VERTICAL);box.setGravity(android.view.Gravity.CENTER);box.setPadding(40,30,40,30);GradientDrawable bg=new GradientDrawable();bg.setColors(new int[]{0xFF7B1FA2,0xFFFF4081,0xFFFFD700});bg.setOrientation(GradientDrawable.Orientation.TL_BR);bg.setCornerRadius(40);box.setBackground(bg);TextView big=new TextView(this);big.setText(getGiftEmoji(gName));big.setTextSize(110);big.setGravity(android.view.Gravity.CENTER);box.addView(big);TextView t1=new TextView(this);t1.setText(sName+"  ➡️  "+rName);t1.setTextColor(0xFFFFFFFF);t1.setTextSize(17);t1.setTypeface(null,android.graphics.Typeface.BOLD);t1.setGravity(android.view.Gravity.CENTER);box.addView(t1);TextView t2=new TextView(this);t2.setText(count+"x "+gName+"  •  ID: "+rId);t2.setTextColor(0xFFFFD700);t2.setTextSize(18);t2.setTypeface(null,android.graphics.Typeface.BOLD);t2.setGravity(android.view.Gravity.CENTER);box.addView(t2);android.widget.FrameLayout.LayoutParams lp=new android.widget.FrameLayout.LayoutParams(android.widget.FrameLayout.LayoutParams.WRAP_CONTENT, android.widget.FrameLayout.LayoutParams.WRAP_CONTENT);lp.gravity=android.view.Gravity.CENTER;overlay.addView(box, lp);box.post(()->{int screenW=decor.getWidth();int screenH=decor.getHeight();int boxW=box.getWidth();int boxH=box.getHeight();float startX=-boxW;float startY=screenH*0.35f;float endX;float endY;if(targetView!=null){int[] loc=new int[2];targetView.getLocationOnScreen(loc);endX=loc[0]+targetView.getWidth()/2f-boxW/2f;endY=loc[1]+targetView.getHeight()/2f-boxH/2f-100;}else{endX=screenW-boxW-40;endY=screenH*0.22f;}box.setX(startX);box.setY(startY);box.setScaleX(0.5f);box.setScaleY(0.5f);box.setAlpha(0f);box.animate().alpha(1f).scaleX(1.2f).scaleY(1.2f).x(screenW/2f-boxW/2f).y(screenH/2f-boxH/2f).setDuration(600).withEndAction(()->{box.animate().scaleX(1.0f).scaleY(1.0f).x(endX).y(endY).setDuration(900).withEndAction(()->{box.animate().scaleX(1.5f).scaleY(1.5f).alpha(0f).setDuration(500).withEndAction(()->{try{decor.removeView(overlay);}catch(Exception ignored){}}).start();}).start();}).start();});}catch(Exception ignored){}}
private void showVipEntryEffect(String uid,String name){fetchVipForUser(uid,vip->{String msg;if(vip>=1&&vip<=8)msg=getVipEmoji(vip)+" "+name+" entered the room";else msg=name+" entered the room";String finalMsg=msg;try{TextView banner=new TextView(this);banner.setText(finalMsg);banner.setTextColor(0xFFFFFFFF);banner.setTextSize(13);banner.setTypeface(null,android.graphics.Typeface.BOLD);banner.setGravity(android.view.Gravity.CENTER_VERTICAL);banner.setBackgroundColor(0xCC000000);banner.setPadding(24,14,24,14);banner.setSingleLine(true);banner.setEllipsize(android.text.TextUtils.TruncateAt.END);android.widget.FrameLayout decor=(android.widget.FrameLayout)getWindow().getDecorView();android.widget.FrameLayout.LayoutParams lp=new android.widget.FrameLayout.LayoutParams(android.widget.FrameLayout.LayoutParams.WRAP_CONTENT,android.widget.FrameLayout.LayoutParams.WRAP_CONTENT);lp.gravity=android.view.Gravity.BOTTOM|android.view.Gravity.START;lp.bottomMargin=160;decor.addView(banner,lp);banner.post(()->{int screenW=decor.getWidth();int bannerW=banner.getWidth();banner.setTranslationX(screenW);banner.animate().translationX(-bannerW-50).setDuration(3500).withEndAction(()->{try{decor.removeView(banner);}catch(Exception ignored){}}).start();});if(vip>=1&&vip<=8){TextView vipBanner=new TextView(this);vipBanner.setText(getVipEmoji(vip)+"  VIP "+vip+"  "+name);vipBanner.setTextColor(0xFFFFD700);vipBanner.setTextSize(20);vipBanner.setTypeface(null,android.graphics.Typeface.BOLD);vipBanner.setGravity(android.view.Gravity.CENTER);vipBanner.setBackgroundColor(0xAA1A0B2E);vipBanner.setPadding(30,30,30,30);android.widget.FrameLayout.LayoutParams lp2=new android.widget.FrameLayout.LayoutParams(android.widget.FrameLayout.LayoutParams.MATCH_PARENT,android.widget.FrameLayout.LayoutParams.WRAP_CONTENT);lp2.gravity=android.view.Gravity.CENTER;decor.addView(vipBanner,lp2);vipBanner.postDelayed(()->{try{decor.removeView(vipBanner);}catch(Exception ignored){}},1800);}}catch(Exception ignored){}});}
private void listenEntryEffect(){activeRoomRef.child("online_users").addChildEventListener(new ChildEventListener(){@Override public void onChildAdded(@NonNull DataSnapshot snap,String p){if(snap==null||snap.getKey()==null||snap.getKey().equals(myId))return;String n=snap.child("name").getValue(String.class);if(n==null)n="User";showVipEntryEffect(snap.getKey(),n);}@Override public void onChildChanged(@NonNull DataSnapshot s,String p){}@Override public void onChildRemoved(@NonNull DataSnapshot s){}@Override public void onChildMoved(@NonNull DataSnapshot s,String p){}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private String getMyPhotoFromAllPlaces(){if(prefs==null)return "";String[] keys={"USER_PHOTO","PROFILE_PHOTO","USER_PHOTO_URL","PHOTO_URL","photo","profile_photo","USER_PHOTO_URL","PHOTO_URL","photo","profile_photo","USER_IMAGE","PROFILE_IMAGE","userPhoto","imageUrl","avatar","profileImage"};for(String k:keys){String v=prefs.getString(k,"");if(v!=null&&!v.trim().isEmpty()&&!v.equals("null"))return v.trim();}if(myPhoto!=null&&!myPhoto.trim().isEmpty())return myPhoto.trim();return "";}
private String getMyHeadwearFromAllPlaces(){if(prefs==null)return "";String[] keys={"HEADWEAR_IMAGE","headwearImage","HEADWEAR_URL","headwearUrl","HEADWEAR","headwear","HEADWEAR_PHOTO"};for(String k:keys){String v=prefs.getString(k,"");if(v!=null&&!v.trim().isEmpty()&&!v.equals("null"))return v.trim();}return "";}
private String getSafePhotoForUpload(){String p=getMyPhotoFromAllPlaces();if(p!=null&&!p.trim().isEmpty()&&!p.equals("null"))return p.trim();if(myPhoto!=null&&!myPhoto.trim().isEmpty()&&!myPhoto.equals("null"))return myPhoto.trim();return "";}
private void loadPhotoInto(ImageView iv,String url){if(iv==null)return;if(url==null||url.trim().isEmpty()||url.equals("null")){iv.setImageDrawable(null);return;}try{if(url.trim().startsWith("http"))Glide.with(this).load(url).circleCrop().into(iv);else if(url.trim().startsWith("content://")||url.trim().startsWith("file://"))Glide.with(this).load(Uri.parse(url.trim())).circleCrop().into(iv);else{byte[] bytes=Base64.decode(url.trim(),Base64.DEFAULT);Glide.with(this).load(bytes).circleCrop().into(iv);}}catch(Exception e){}}
private void loadSeatPhoto(ImageView iv,TextView letterTv,String photoUrl,String name){if(iv==null||letterTv==null)return;if(photoUrl!=null&&!photoUrl.trim().isEmpty()&&!photoUrl.equals("null")){letterTv.setVisibility(View.GONE);iv.setVisibility(View.VISIBLE);try{if(photoUrl.trim().startsWith("http"))Glide.with(this).load(photoUrl.trim()).circleCrop().into(iv);else if(photoUrl.trim().startsWith("content://")||photoUrl.trim().startsWith("file://"))Glide.with(this).load(Uri.parse(photoUrl.trim())).circleCrop().into(iv);else{byte[] b=Base64.decode(photoUrl.trim(),Base64.DEFAULT);Glide.with(this).load(b).circleCrop().into(iv);}}catch(Exception e){iv.setVisibility(View.GONE);letterTv.setVisibility(View.VISIBLE);letterTv.setText(name.isEmpty()?"U":name.substring(0,1).toUpperCase());}}else{iv.setVisibility(View.GONE);iv.setImageDrawable(null);letterTv.setVisibility(View.VISIBLE);letterTv.setText(name.isEmpty()?"U":name.substring(0,1).toUpperCase());}}
private void loadRoomPhotoInto(ImageView iv){if(iv==null)return;String url=currentRoomPhotoUrl;if(url==null||url.trim().isEmpty()||url.equals("null")||url.trim().startsWith("content://")||url.trim().startsWith("file://")){try{iv.setImageResource(R.mipmap.ic_launcher);}catch(Exception e){iv.setImageDrawable(null);}return;}loadPhotoInto(iv,url);}
private void loadHeadwearInto(ImageView iv,String url){if(iv==null)return;if(url==null||url.trim().isEmpty()||url.equals("null")){iv.setVisibility(View.GONE);return;}iv.setVisibility(View.VISIBLE);try{if(url.trim().startsWith("http")||url.trim().startsWith("content://")||url.trim().startsWith("file://"))Glide.with(this).load(url.trim()).into(iv);else{byte[] bytes=Base64.decode(url.trim(),Base64.DEFAULT);Bitmap bmp=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bmp!=null)iv.setImageBitmap(bmp);else iv.setVisibility(View.GONE);}}catch(Exception e){iv.setVisibility(View.GONE);}}
private String getThemeUrl(String theme){if("Desert Sunset".equals(theme))return "https://images.pexels.com/photos/1680140/pexels-photo-1680140.jpeg?auto=compress&cs=tinysrgb&w=1080";if("Mosque Night".equals(theme))return "https://images.pexels.com/photos/1537086/pexels-photo-1537086.jpeg?auto=compress&cs=tinysrgb&w=1080";if("Sea Couple".equals(theme))return "https://images.pexels.com/photos/1549326/pexels-photo-1549326.jpeg?auto=compress&cs=tinysrgb&w=1080";return "";}
private void applyTheme(String theme){selectedTheme=theme;if(imgRoomBackground==null)return;String url=getThemeUrl(theme);if(url.isEmpty()){imgRoomBackground.setImageDrawable(null);imgRoomBackground.setBackgroundColor(0xFFFFF8E1);return;}try{Glide.with(this).load(url).centerCrop().into(imgRoomBackground);}catch(Exception e){}}
private void openThemePicker(TextView tvTheme,ImageView thumb){String[] themes={"Desert Sunset","Mosque Night","Sea Couple","Default"};new AlertDialog.Builder(this).setTitle("Room theme - Free").setItems(themes,(d,w)->{selectedTheme=themes[w];if(tvTheme!=null)tvTheme.setText("Theme: "+selectedTheme);applyTheme(selectedTheme);if(thumb!=null){String u=getThemeUrl(selectedTheme);if(!u.isEmpty())Glide.with(this).load(u).centerCrop().into(thumb);}}).setNegativeButton("Cancel",null).show();}
private void setupSeats(){for(int i=0;i<10;i++){int seatId=getResources().getIdentifier("seat_"+i,"id",getPackageName());int imgId=getResources().getIdentifier("seatImg_"+i,"id",getPackageName());int letterId=getResources().getIdentifier("seatLetter_"+i,"id",getPackageName());View seat=findViewById(seatId);ImageView img=findViewById(imgId);TextView letter=findViewById(letterId);seatViews[i]=seat;seatImgViews[i]=img;seatLetterViews[i]=letter;if(seat instanceof android.widget.LinearLayout){android.widget.LinearLayout ll=(android.widget.LinearLayout)seat;if(ll.getChildCount()>=2&&ll.getChildAt(1) instanceof TextView)seatNameViews[i]=(TextView)ll.getChildAt(1);}final int seatIndex=i;if(seat!=null)seat.setOnClickListener(v->onSeatClicked(seatIndex));if(img!=null)img.setOnClickListener(v->onSeatClicked(seatIndex));if(letter!=null)letter.setOnClickListener(v->onSeatClicked(seatIndex));}listenSeats();}
private void listenSeats(){activeRoomRef.child("seats").addValueEventListener(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){seatUserId.clear();seatUserName.clear();seatUserPhoto.clear();seatMuted.clear();seatLocked.clear();for(DataSnapshot c:snap.getChildren()){String key=c.getKey();if(key==null)continue;String uid=c.child("userId").getValue(String.class);if(uid==null||uid.isEmpty()){Boolean l2=c.child("locked").getValue(Boolean.class);if(l2!=null&&l2)seatLocked.put(key,true);continue;}seatUserId.put(key,uid);String n=c.child("name").getValue(String.class);seatUserName.put(key,n==null?"User":n);String ph=c.child("photo").getValue(String.class);seatUserPhoto.put(key,ph==null?"":ph);Boolean m=c.child("muted").getValue(Boolean.class);seatMuted.put(key,m!=null&&m);Boolean l=c.child("locked").getValue(Boolean.class);seatLocked.put(key,l!=null&&l);}updateAllSeatsUI();}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void updateAllSeatsUI(){for(int i=0;i<10;i++){String key="seat_"+i;ImageView img=seatImgViews[i];TextView letter=seatLetterViews[i];TextView nameTv=seatNameViews[i];if(letter==null)continue;String uid=seatUserId.get(key);if(uid==null||uid.isEmpty()){boolean locked=seatLocked.get(key)!=null&&seatLocked.get(key);if(img!=null){img.setVisibility(View.GONE);img.setImageDrawable(null);}letter.setVisibility(View.VISIBLE);letter.setText(locked?"🔒":"🛋️");if(nameTv!=null)nameTv.setText(i==0?"Host":(locked?"Locked":""));if(seatViews[i]!=null)seatViews[i].setBackground(null);}else{String name=seatUserName.get(key);if(name==null)name="User";boolean muted=seatMuted.get(key)!=null&&seatMuted.get(key);String photo=seatUserPhoto.get(key);if(photo==null)photo="";loadSeatPhoto(img,letter,photo,name);Integer cachedVip=seatVipCache.get(uid);if(cachedVip!=null&&cachedVip>0){if(nameTv!=null)nameTv.setText(getVipEmoji(cachedVip)+" "+name+(muted?" 🔇":""));if(seatViews[i]!=null){GradientDrawable bg=new GradientDrawable();bg.setColors(getVipBgColors(cachedVip));bg.setOrientation(GradientDrawable.Orientation.TOP_BOTTOM);bg.setCornerRadius(28);seatViews[i].setBackground(bg);}}else{if(nameTv!=null)nameTv.setText(name+(muted?" 🔇":""));if(seatViews[i]!=null)seatViews[i].setBackground(null);final String fUid=uid;final int fI=i;final String fName=name;final boolean fMuted=muted;fetchVipForUser(fUid,vip->{seatVipCache.put(fUid,vip);if(vip>0){if(seatNameViews[fI]!=null)seatNameViews[fI].setText(getVipEmoji(vip)+" "+fName+(fMuted?" 🔇":""));if(seatViews[fI]!=null){GradientDrawable bg2=new GradientDrawable();bg2.setColors(getVipBgColors(vip));bg2.setOrientation(GradientDrawable.Orientation.TOP_BOTTOM);bg2.setCornerRadius(28);seatViews[fI].setBackground(bg2);}}});}}}}
private int mySeatIndex(){for(int i=0;i<10;i++){String uid=seatUserId.get("seat_"+i);if(myId.equals(uid))return i;}return -1;}
private void onSeatClicked(int seatIndex){String key="seat_"+seatIndex;String occupantId=seatUserId.get(key);boolean isEmpty=occupantId==null||occupantId.isEmpty();boolean locked=seatLocked.get(key)!=null&&seatLocked.get(key);boolean isMine=myId.equals(occupantId);boolean iAmOwnerOrAdmin=amIOwner||amIAdmin;List<String> options=new ArrayList<>();List<Runnable> actions=new ArrayList<>();if(isEmpty){if(locked&&!iAmOwnerOrAdmin){Toast.makeText(this,"This seat is Locked",Toast.LENGTH_SHORT).show();return;}if(mySeatIndex()==-1){options.add("On Mic");final int f1=seatIndex;actions.add(()->takeSeat(f1));}else{options.add("Change Seat");final int f2=seatIndex;final int fMy=mySeatIndex();actions.add(()->changeSeat(fMy,f2));}if(iAmOwnerOrAdmin){options.add("Invite");final int f3=seatIndex;actions.add(()->inviteToSeat(f3));final boolean fL=locked;final int f4=seatIndex;options.add(fL?"Unlock Seat":"Lock Seat");actions.add(()->toggleLockSeat(f4));}}else if(isMine){boolean muted=seatMuted.get(key)!=null&&seatMuted.get(key);final int f5=seatIndex;options.add("Leave the Mic");actions.add(()->leaveSeat(f5));final int f6=seatIndex;options.add(muted?"Unmute":"Mute");actions.add(()->toggleMuteSeat(f6));final String fName=seatUserName.get(key)==null?"User":seatUserName.get(key);final String fPhoto=seatUserPhoto.get(key)==null?"":seatUserPhoto.get(key);options.add("Profile");actions.add(()->openUserProfile(myId,fName,fPhoto));}else{final String finalOccupantId=occupantId;final String finalOccName=seatUserName.get(key)==null?"User":seatUserName.get(key);final String finalOccPhoto=seatUserPhoto.get(key)==null?"":seatUserPhoto.get(key);boolean muted=seatMuted.get(key)!=null&&seatMuted.get(key);final boolean fMuted=muted;if(iAmOwnerOrAdmin){options.add("Profile");actions.add(()->openUserProfile(finalOccupantId,finalOccName,finalOccPhoto));final int f7=seatIndex;options.add(fMuted?"Unmute":"Mute");actions.add(()->toggleMuteSeat(f7));final int f8=seatIndex;options.add("Kick");actions.add(()->kickSeat(f8));final boolean fL2=locked;final int f9=seatIndex;options.add(fL2?"Unlock Seat":"Lock Seat");actions.add(()->toggleLockSeat(f9));}else{options.add("Profile");actions.add(()->openUserProfile(finalOccupantId,finalOccName,finalOccPhoto));}options.add("🎁 Send Gift");actions.add(()->openGiftDialog(finalOccupantId,finalOccName));}if(options.isEmpty())return;String title="Seat "+(seatIndex+1)+(isEmpty?" - Empty":" - "+seatUserName.get(key));new AlertDialog.Builder(this).setTitle(title).setItems(options.toArray(new String[0]),(d,w)->actions.get(w).run()).setNegativeButton("Cancel",null).show();}
private void takeSeat(int seatIndex){String key="seat_"+seatIndex;if(seatLocked.get(key)!=null&&seatLocked.get(key)&&!amIOwner&&!amIAdmin){Toast.makeText(this,"This seat is Locked",Toast.LENGTH_SHORT).show();return;}if(mySeatIndex()!=-1&&mySeatIndex()!=seatIndex){changeSeat(mySeatIndex(),seatIndex);return;}String safePhoto=getSafePhotoForUpload();Map<String,Object> m=new HashMap<>();m.put("userId",myId);m.put("name",myName);if(!safePhoto.isEmpty())m.put("photo",safePhoto);m.put("muted",false);m.put("locked",seatLocked.get(key)!=null&&seatLocked.get(key));activeRoomRef.child("seats").child(key).setValue(m);Toast.makeText(this,"You are on Seat "+(seatIndex+1),Toast.LENGTH_SHORT).show();}
private void changeSeat(int oldSeatIndex,int newSeatIndex){String oldKey="seat_"+oldSeatIndex;String newKey="seat_"+newSeatIndex;if(seatLocked.get(newKey)!=null&&seatLocked.get(newKey)&&!amIOwner&&!amIAdmin){Toast.makeText(this,"This seat is Locked",Toast.LENGTH_SHORT).show();return;}String safePhoto=getSafePhotoForUpload();Map<String,Object> updates=new HashMap<>();updates.put("seats/"+oldKey,null);Map<String,Object> m=new HashMap<>();m.put("userId",myId);m.put("name",myName);if(!safePhoto.isEmpty())m.put("photo",safePhoto);m.put("muted",false);m.put("locked",seatLocked.get(newKey)!=null&&seatLocked.get(newKey));updates.put("seats/"+newKey,m);activeRoomRef.updateChildren(updates);Toast.makeText(this,"Moved to Seat "+(newSeatIndex+1),Toast.LENGTH_SHORT).show();}
private void leaveSeat(int seatIndex){activeRoomRef.child("seats").child("seat_"+seatIndex).removeValue();Toast.makeText(this,"Left the Mic",Toast.LENGTH_SHORT).show();}
private void kickSeat(int seatIndex){activeRoomRef.child("seats").child("seat_"+seatIndex).removeValue();Toast.makeText(this,"Kicked from Seat",Toast.LENGTH_SHORT).show();}
private void toggleMuteSeat(int seatIndex){String key="seat_"+seatIndex;boolean cur=seatMuted.get(key)!=null&&seatMuted.get(key);activeRoomRef.child("seats").child(key).child("muted").setValue(!cur);Toast.makeText(this,!cur?"Muted":"Unmuted",Toast.LENGTH_SHORT).show();}
private void toggleLockSeat(int seatIndex){String key="seat_"+seatIndex;boolean cur=seatLocked.get(key)!=null&&seatLocked.get(key);if(seatUserId.get(key)==null){if(!cur){Map<String,Object> m=new HashMap<>();m.put("userId","");m.put("name","");m.put("photo","");m.put("muted",false);m.put("locked",true);activeRoomRef.child("seats").child(key).setValue(m);}else activeRoomRef.child("seats").child(key).removeValue();}else activeRoomRef.child("seats").child(key).child("locked").setValue(!cur);Toast.makeText(this,!cur?"Seat Locked":"Seat Unlocked",Toast.LENGTH_SHORT).show();}
private void inviteToSeat(final int seatIndex){BottomSheetDialog d=new BottomSheetDialog(this);View v=LayoutInflater.from(this).inflate(R.layout.dialog_online_list,null);d.setContentView(v);RecyclerView rv=v.findViewById(R.id.rvOnlineList);if(rv!=null)rv.setLayoutManager(new LinearLayoutManager(this));List<Map<String,String>> list=new ArrayList<>();RecyclerView.Adapter adapter=new RecyclerView.Adapter<RecyclerView.ViewHolder>(){@NonNull @Override public RecyclerView.ViewHolder onCreateViewHolder(@NonNull android.view.ViewGroup p,int t){View item=LayoutInflater.from(p.getContext()).inflate(R.layout.item_user,p,false);return new RecyclerView.ViewHolder(item){};}@Override public void onBindViewHolder(@NonNull RecyclerView.ViewHolder h,int pos){Map<String,String> u=list.get(pos);ImageView iv=h.itemView.findViewById(R.id.imgChatPhoto);TextView tvH=h.itemView.findViewById(R.id.userName);TextView tvM=h.itemView.findViewById(R.id.tvChatMsg);loadPhotoInto(iv,u.get("photo"));if(tvH!=null)tvH.setText(u.get("name")+"  Lv."+u.get("level"));if(tvM!=null)tvM.setText("ID: "+u.get("id")+" - Tap to Invite");h.itemView.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("userId",u.get("id"));m.put("name",u.get("name"));m.put("photo",u.get("photo"));m.put("muted",false);m.put("locked",false);activeRoomRef.child("seats").child("seat_"+seatIndex).setValue(m);Toast.makeText(VoiceRoomActivity.this,u.get("name")+" invited to Seat",Toast.LENGTH_SHORT).show();d.dismiss();});}@Override public int getItemCount(){return list.size();}};if(rv!=null)rv.setAdapter(adapter);activeRoomRef.child("online_users").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){list.clear();for(DataSnapshot c:snap.getChildren()){Map<String,String> m=new HashMap<>();m.put("name",c.child("name").getValue(String.class)==null?"User":c.child("name").getValue(String.class));String ph=c.child("photo").getValue(String.class);if(ph==null||ph.isEmpty())ph=c.child("photoUrl").getValue(String.class);m.put("photo",ph==null?"":ph);Object lvl=c.child("level").getValue();m.put("level",lvl==null?"1":String.valueOf(lvl));m.put("id",c.getKey());if(!c.getKey().equals(myId))list.add(m);}adapter.notifyDataSetChanged();}@Override public void onCancelled(@NonNull DatabaseError e){}});View btnClose=v.findViewById(R.id.btnCloseOnline);if(btnClose!=null)btnClose.setOnClickListener(x->d.dismiss());d.show();}
private void openUserProfile(String targetId,String targetName,String targetPhoto){openMiniProfile(targetId,targetName,targetPhoto);}
