private void openMiniProfile(String targetId,String targetName,String targetPhoto){BottomSheetDialog d=new BottomSheetDialog(this);View v=LayoutInflater.from(this).inflate(R.layout.dialog_mini_profile,null);d.setContentView(v);ImageView img=v.findViewById(R.id.imgMiniPhoto);ImageView imgFrame=v.findViewById(R.id.imgMiniFrame);TextView tvName=v.findViewById(R.id.txtMiniName);TextView tvVipBadge=v.findViewById(R.id.txtMiniVipBadge);TextView tvGenderIcon=v.findViewById(R.id.txtMiniGenderIcon);TextView tvFlag=v.findViewById(R.id.txtMiniFlag);TextView tvGenderCountry=v.findViewById(R.id.txtMiniGenderCountry);TextView tvLevel=v.findViewById(R.id.txtMiniLevel);TextView tvSending=v.findViewById(R.id.txtMiniSending);TextView tvReceiving=v.findViewById(R.id.txtMiniReceiving);TextView tvId=v.findViewById(R.id.txtMiniId);View layoutAgency=v.findViewById(R.id.layoutMiniAgency);TextView tvAgency=v.findViewById(R.id.txtMiniAgency);View layoutHost=v.findViewById(R.id.layoutMiniHost);TextView tvHost=v.findViewById(R.id.txtMiniHost);View btnAdd=v.findViewById(R.id.btnMiniAddLeft);View btnGift=v.findViewById(R.id.btnMiniGift);View btnFollow=v.findViewById(R.id.btnMiniFollowRight);View root=v.findViewById(R.id.layoutMiniRoot);final String fName=targetName==null?"User":targetName;if(tvName!=null)tvName.setText(fName);if(tvId!=null)tvId.setText("ID: "+targetId+"  📋");if(img!=null&&targetPhoto!=null&&!targetPhoto.isEmpty())loadPhotoInto(img,targetPhoto);if(tvId!=null)tvId.setOnClickListener(x->{ClipboardManager cm=(ClipboardManager)getSystemService(Context.CLIPBOARD_SERVICE);if(cm!=null)cm.setPrimaryClip(ClipData.newPlainText("ID",targetId));Toast.makeText(this,"ID Copied",Toast.LENGTH_SHORT).show();});if(tvSending!=null)tvSending.setVisibility(View.GONE);if(tvReceiving!=null)tvReceiving.setVisibility(View.GONE);if(tvGenderCountry!=null)tvGenderCountry.setVisibility(View.GONE);if(root!=null)root.setOnClickListener(x->{d.dismiss();try{android.content.Intent i=new android.content.Intent(this,PublicProfileActivity.class);i.putExtra("TARGET_9DIGIT_ID",targetId);i.putExtra("TARGET_NAME",fName);startActivity(i);}catch(Exception e){Toast.makeText(this,"Profile cannot be opened",Toast.LENGTH_SHORT).show();}});if(btnAdd!=null)btnAdd.setOnClickListener(x->Toast.makeText(this,"Friend Request Sent to "+fName,Toast.LENGTH_SHORT).show());if(btnFollow!=null)btnFollow.setOnClickListener(x->Toast.makeText(this,"Followed! ❤️",Toast.LENGTH_SHORT).show());if(btnGift!=null)btnGift.setOnClickListener(x->{d.dismiss();openGiftDialog(targetId,fName);});fetchVipForUser(targetId,vip->{if(vip>=1&&vip<=8){if(tvVipBadge!=null){tvVipBadge.setVisibility(View.VISIBLE);tvVipBadge.setText(getVipEmoji(vip)+" VIP "+vip+" • "+getVipName(vip));}if(root!=null){GradientDrawable bg=new GradientDrawable();bg.setColors(getVipBgColors(vip));bg.setOrientation(GradientDrawable.Orientation.TOP_BOTTOM);bg.setCornerRadius(32);root.setBackground(bg);}if(imgFrame!=null){imgFrame.setVisibility(View.VISIBLE);imgFrame.setBackgroundResource(android.R.drawable.dialog_holo_light_frame);}}else{if(tvVipBadge!=null)tvVipBadge.setVisibility(View.GONE);if(imgFrame!=null)imgFrame.setVisibility(View.GONE);}});resolveUserKeyByProfileId(targetId,key->{if(key==null||key.isEmpty())return;FirebaseDatabase.getInstance().getReference("users").child(key).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot ds){String name=ds.child("name").getValue()==null?fName:String.valueOf(ds.child("name").getValue());String gender=ds.child("gender").getValue()==null?"":String.valueOf(ds.child("gender").getValue());String country=ds.child("country").getValue()==null?"":String.valueOf(ds.child("country").getValue());long sendingL=Math.max(getLongVal(ds,"sending"),getLongVal(ds,"totalSending"));long receivingL=Math.max(getLongVal(ds,"receiving"),getLongVal(ds,"totalReceiving"));int wealthL=LevelUtils.calculateWealthLevel(sendingL);int charmL=LevelUtils.calculateCharmLevel(receivingL);String photo="";if(ds.child("photoUrl").getValue()!=null)photo=String.valueOf(ds.child("photoUrl").getValue());if(photo.isEmpty()&&ds.child("photo").getValue()!=null)photo=String.valueOf(ds.child("photo").getValue());if(photo.isEmpty()&&ds.child("photoBase64").getValue()!=null)photo=String.valueOf(ds.child("photoBase64").getValue());String flagCode=getCountryShort(country);String gIcon=getGenderIconPremium(gender);if(gIcon.isEmpty()){String gLow=gender.toLowerCase();boolean isFemale=gLow.contains("female");boolean isMale=!isFemale&&gLow.contains("male");gIcon=isFemale?"♀️":(isMale?"♂️":"");}if(tvName!=null)tvName.setText(name+"  "+flagCode+"  "+gIcon);if(tvId!=null)tvId.setText("ID: "+targetId+"  📋");if(tvGenderIcon!=null){tvGenderIcon.setText(gIcon);String gLow2=gender.toLowerCase();if(gLow2.contains("female"))tvGenderIcon.setTextColor(0xFFFF69B4);else if(gLow2.contains("male"))tvGenderIcon.setTextColor(0xFF00B0FF);else tvGenderIcon.setTextColor(0xFFFFFFFF);}if(tvFlag!=null)tvFlag.setText(flagCode);if(tvLevel!=null){tvLevel.setText("💎 Wealth Lv."+wealthL+"  •  💖 Charm Lv."+charmL);GradientDrawable bg=new GradientDrawable();bg.setColors(LevelUtils.getLevelColors(wealthL));bg.setOrientation(GradientDrawable.Orientation.LEFT_RIGHT);bg.setCornerRadius(24);tvLevel.setBackground(bg);}if(tvSending!=null)tvSending.setVisibility(View.GONE);if(tvReceiving!=null)tvReceiving.setVisibility(View.GONE);if(!photo.isEmpty()&&img!=null)loadPhotoInto(img,photo);boolean isAgencyUser=false;if(ds.child("isAgency").getValue()!=null&&Boolean.TRUE.equals(ds.child("isAgency").getValue(Boolean.class)))isAgencyUser=true;String agencyStatus=ds.child("agencyStatus").getValue()==null?"":String.valueOf(ds.child("agencyStatus").getValue());if(isAgencyUser&&!"blocked".equalsIgnoreCase(agencyStatus)&&!"rejected".equalsIgnoreCase(agencyStatus)){if(layoutAgency!=null&&tvAgency!=null){layoutAgency.setVisibility(View.VISIBLE);tvAgency.setText("AGENCY");tvAgency.setTextColor(0xFFFFFFFF);}}else{if(layoutAgency!=null)layoutAgency.setVisibility(View.GONE);}String host="";if(ds.child("hostName").getValue()!=null)host=String.valueOf(ds.child("hostName").getValue());if(host.isEmpty()&&ds.child("isHost").getValue()!=null&&Boolean.TRUE.equals(ds.child("isHost").getValue(Boolean.class)))host="Official Host";if(host.isEmpty()&&ds.child("host").getValue()!=null)host=String.valueOf(ds.child("host").getValue());if(!host.isEmpty()&&layoutHost!=null&&tvHost!=null){layoutHost.setVisibility(View.VISIBLE);tvHost.setText(host);}}@Override public void onCancelled(@NonNull DatabaseError e){}});});d.show();}
private void loadGiftTargets(RecyclerView rv,String preselectId){giftTargets.clear();Map<String,String> m1=new HashMap<>();m1.put("id","ALL_MIC");m1.put("name","All Mic");m1.put("photo","");giftTargets.add(m1);Map<String,String> m2=new HashMap<>();m2.put("id","ALL_ROOM");m2.put("name","All Room");m2.put("photo","");giftTargets.add(m2);Map<String,String> me=new HashMap<>();me.put("id",myId);me.put("name",myName+" (You)");me.put("photo",getMyPhotoFromAllPlaces());giftTargets.add(me);selectedGiftTargetId=preselectId==null||preselectId.isEmpty()?myId:preselectId;selectedGiftTargetName="";activeRoomRef.child("online_users").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){Set<String> seen=new HashSet<>();seen.add("ALL_MIC");seen.add("ALL_ROOM");seen.add(myId);for(DataSnapshot c:snap.getChildren()){if(c.getKey()==null||seen.contains(c.getKey()))continue;seen.add(c.getKey());Map<String,String> m=new HashMap<>();m.put("id",c.getKey());String n=c.child("name").getValue(String.class);m.put("name",n==null?"User":n);String ph=c.child("photo").getValue(String.class);if(ph==null||ph.isEmpty())ph=c.child("photoUrl").getValue(String.class);m.put("photo",ph==null?"":ph);giftTargets.add(m);}for(Map<String,String> m:giftTargets)if(m.get("id").equals(selectedGiftTargetId))selectedGiftTargetName=m.get("name");if(selectedGiftTargetName==null||selectedGiftTargetName.isEmpty())selectedGiftTargetName=selectedGiftTargetId;if(giftTargetAdapter!=null)giftTargetAdapter.notifyDataSetChanged();}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void openGiftDialog(String targetId,String targetName){BottomSheetDialog d=new BottomSheetDialog(this);View v;try{v=LayoutInflater.from(this).inflate(R.layout.dialog_gift_panel,null);}catch(Exception e){Toast.makeText(this,"Gift - Coming Soon",Toast.LENGTH_SHORT).show();return;}d.setContentView(v);selectedGiftCount=1;selectedGiftName="Rose";selectedGiftPrice=10;TextView tvBal=v.findViewById(R.id.txtUserCoinBalance);currentGiftBalanceView=tvBal;if(tvBal!=null)tvBal.setText("💰 "+getMyCoins()+" Coins");d.setOnDismissListener(dlg->{currentGiftBalanceView=null;});EditText etTarget=v.findViewById(R.id.editTargetSeat);if(etTarget!=null)etTarget.setText(targetName==null?"":targetName);TextView tvSelectedTarget=v.findViewById(R.id.tvSelectedTargetId);if(tvSelectedTarget!=null)tvSelectedTarget.setText("To: "+(targetName==null||targetName.isEmpty()?"All Mic":targetName));Button btnQty=v.findViewById(R.id.btnGiftQuantity);if(btnQty!=null){btnQty.setText("x"+selectedGiftCount);btnQty.setOnClickListener(x->{String[] opts={"x1","x5","x10"};new AlertDialog.Builder(this).setTitle("Select Quantity").setItems(opts,(dd,w)->{selectedGiftCount=w==0?1:(w==1?5:10);btnQty.setText("x"+selectedGiftCount);}).setNegativeButton("Cancel",null).show();});}RecyclerView rvT=v.findViewById(R.id.rvGiftTargets);if(rvT!=null){rvT.setLayoutManager(new LinearLayoutManager(this,LinearLayoutManager.HORIZONTAL,false));giftTargetAdapter=new RecyclerView.Adapter<RecyclerView.ViewHolder>(){@NonNull @Override public RecyclerView.ViewHolder onCreateViewHolder(@NonNull android.view.ViewGroup p,int t){View item=LayoutInflater.from(p.getContext()).inflate(R.layout.item_gift_target,p,false);return new RecyclerView.ViewHolder(item){};}@Override public void onBindViewHolder(@NonNull RecyclerView.ViewHolder h,int pos){Map<String,String> u=giftTargets.get(pos);ImageView iv=h.itemView.findViewById(R.id.imgTargetPhoto);TextView tvN=h.itemView.findViewById(R.id.txtTargetName);TextView tvL=h.itemView.findViewById(R.id.txtTargetLabel);String id=u.get("id");if(tvN!=null)tvN.setText(u.get("name"));if(tvL!=null){if("ALL_MIC".equals(id))tvL.setText("All Mic");else if("ALL_ROOM".equals(id))tvL.setText("All Room");else tvL.setText("ID: "+id);}if(iv!=null){if("ALL_MIC".equals(id)){iv.setImageResource(android.R.drawable.ic_btn_speak_now);}else if("ALL_ROOM".equals(id)){iv.setImageResource(android.R.drawable.ic_menu_myplaces);}else loadPhotoInto(iv,u.get("photo"));}h.itemView.setBackgroundResource(selectedGiftTargetId.equals(id)?android.R.drawable.dialog_holo_light_frame:0);h.itemView.setOnClickListener(x->{selectedGiftTargetId=id;selectedGiftTargetName=u.get("name");if(etTarget!=null)etTarget.setText(selectedGiftTargetName);if(tvSelectedTarget!=null)tvSelectedTarget.setText("To: "+selectedGiftTargetName);notifyDataSetChanged();});}@Override public int getItemCount(){return giftTargets.size();}};rvT.setAdapter(giftTargetAdapter);loadGiftTargets(rvT,targetId);}RecyclerView rv=v.findViewById(R.id.rvGifts);if(rv!=null){rv.setLayoutManager(new GridLayoutManager(this,4));String[] giftNames={"Rose","Heart","Cake","Diamond","Car","Crown","Plane","Castle"};String[] giftEmojis={"🌹","❤️","🎂","💎","🚗","👑","✈️","🏰"};int[] giftPrices={10,50,200,100,500,1000,2000,5000};RecyclerView.Adapter a=new RecyclerView.Adapter<RecyclerView.ViewHolder>(){@NonNull @Override public RecyclerView.ViewHolder onCreateViewHolder(@NonNull android.view.ViewGroup p,int t){View item;try{item=LayoutInflater.from(p.getContext()).inflate(R.layout.item_gift_card,p,false);}catch(Exception e){TextView tv=new TextView(p.getContext());tv.setLayoutParams(new android.view.ViewGroup.LayoutParams(android.view.ViewGroup.LayoutParams.MATCH_PARENT,160));tv.setGravity(android.view.Gravity.CENTER);tv.setTextColor(0xFFFFFFFF);tv.setTextSize(13);tv.setPadding(8,8,8,8);tv.setBackgroundColor(0xFF2A1B4E);item=tv;}return new RecyclerView.ViewHolder(item){};}@Override public void onBindViewHolder(@NonNull RecyclerView.ViewHolder h,int pos){TextView tvE=h.itemView.findViewById(R.id.txtGiftEmoji);TextView tvN=h.itemView.findViewById(R.id.txtGiftName);TextView tvP=h.itemView.findViewById(R.id.txtGiftPrice);if(tvE!=null)tvE.setText(giftEmojis[pos]);if(tvN!=null)tvN.setText(giftNames[pos]);if(tvP!=null)tvP.setText(giftPrices[pos]+" Coins");if(tvE==null&&h.itemView instanceof TextView)((TextView)h.itemView).setText(giftEmojis[pos]+"\n"+giftNames[pos]+"\n"+giftPrices[pos]+" Coins");h.itemView.setBackgroundColor(giftNames[pos].equals(selectedGiftName)?0xFFFF4081:0xFF2A1B4E);h.itemView.setOnClickListener(x->{selectedGiftName=giftNames[pos];selectedGiftPrice=giftPrices[pos];notifyDataSetChanged();});}@Override public int getItemCount(){return giftNames.length;}};rv.setAdapter(a);}View btnSend=v.findViewById(R.id.btnSendGift);if(btnSend!=null)btnSend.setOnClickListener(x->{sendGiftNow(d,tvBal);});d.show();}
private void sendGiftNow(BottomSheetDialog d,TextView tvBal){if(selectedGiftTargetId==null||selectedGiftTargetId.isEmpty()){Toast.makeText(this,"Select a target",Toast.LENGTH_SHORT).show();return;}List<Map<String,String>> targets=new ArrayList<>();if("ALL_MIC".equals(selectedGiftTargetId)){for(int i=0;i<10;i++){String uid=seatUserId.get("seat_"+i);if(uid!=null&&!uid.isEmpty()){Map<String,String> m=new HashMap<>();m.put("id",uid);m.put("name",seatUserName.get("seat_"+i)==null?"User":seatUserName.get("seat_"+i));m.put("photo",seatUserPhoto.get("seat_"+i)==null?"":seatUserPhoto.get("seat_"+i));targets.add(m);}}if(targets.isEmpty()){Toast.makeText(this,"No one on Mic",Toast.LENGTH_SHORT).show();return;}doSendGift(targets,d,tvBal);}else if("ALL_ROOM".equals(selectedGiftTargetId)){activeRoomRef.child("online_users").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){List<Map<String,String>> t2=new ArrayList<>();for(DataSnapshot c:snap.getChildren()){Map<String,String> m=new HashMap<>();m.put("id",c.getKey());String n=c.child("name").getValue(String.class);m.put("name",n==null?"User":n);String ph=c.child("photo").getValue(String.class);if(ph==null||ph.isEmpty())ph=c.child("photoUrl").getValue(String.class);m.put("photo",ph==null?"":ph);t2.add(m);}if(t2.isEmpty()){Toast.makeText(VoiceRoomActivity.this,"No one in Room",Toast.LENGTH_SHORT).show();return;}doSendGift(t2,d,tvBal);}@Override public void onCancelled(@NonNull DatabaseError e){}});}else{Map<String,String> m=new HashMap<>();m.put("id",selectedGiftTargetId);m.put("name",selectedGiftTargetName==null||selectedGiftTargetName.isEmpty()?selectedGiftTargetId:selectedGiftTargetName);String tp="";for(Map<String,String> gt:giftTargets)if(gt.get("id").equals(selectedGiftTargetId))tp=gt.get("photo")==null?"":gt.get("photo");m.put("photo",tp);targets.add(m);doSendGift(targets,d,tvBal);}}
private void doSendGift(List<Map<String,String>> targets,BottomSheetDialog d,TextView tvBal){long total=(long)selectedGiftPrice*selectedGiftCount*targets.size();long coinsPerTarget=(long)selectedGiftPrice*selectedGiftCount;resolveUserKeyByProfileId(myId,senderKey->{if(senderKey==null||senderKey.isEmpty()){Toast.makeText(this,"Wallet not found - Login again",Toast.LENGTH_SHORT).show();return;}DatabaseReference senderRef=FirebaseDatabase.getInstance().getReference("users").child(senderKey);senderRef.addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot ss){long realBal=readWalletFromSnap(ss);if(realBal<total){Toast.makeText(VoiceRoomActivity.this,"Not enough Coins! Need "+total+" - You have "+realBal,Toast.LENGTH_LONG).show();return;}long newSenderBal=realBal-total;long curSending=getLongVal(ss,"sending");long curTotalSending=getLongVal(ss,"totalSending");if(curTotalSending==0)curTotalSending=curSending;long curRecv0=getLongVal(ss,"receiving");long curTotalRecv0=getLongVal(ss,"totalReceiving");long curTarget0=getLongVal(ss,"targetCoins");long curTargetTotal0=getLongVal(ss,"totalTargetCoins");boolean hasSelf=false;for(Map<String,String> tt:targets)if(myId!=null&&myId.equals(tt.get("id")))hasSelf=true;long selfExchange=hasSelf?(coinsPerTarget*30)/100:0;long finalWallet=newSenderBal+selfExchange;long newTotalSending=curTotalSending+total;int newWealth=LevelUtils.calculateWealthLevel(newTotalSending);long newTotalRecvSelf=hasSelf?curTotalRecv0+coinsPerTarget:curTotalRecv0;int newCharmSelf=hasSelf?LevelUtils.calculateCharmLevel(newTotalRecvSelf):LevelUtils.calculateCharmLevel(curTotalRecv0);Map<String,Object> su=new HashMap<>();su.put("coins",finalWallet);su.put("coinBalance",finalWallet);su.put("walletCoins",finalWallet);su.put("sendingCoins",finalWallet);su.put("sending",curSending+total);su.put("totalSending",newTotalSending);su.put("wealthLevel",newWealth);su.put("level",String.valueOf(newWealth));su.put("levelValue",newWealth);if(hasSelf){su.put("receiving",curRecv0+coinsPerTarget);su.put("totalReceiving",curTotalRecv0+coinsPerTarget);su.put("targetCoins",curTarget0+coinsPerTarget);su.put("totalTargetCoins",curTargetTotal0+coinsPerTarget);su.put("charmLevel",newCharmSelf);}senderRef.updateChildren(su);myWalletBalance=finalWallet;myLevel=String.valueOf(newWealth);if(tvBal!=null)tvBal.setText("💰 "+finalWallet+" Coins");for(Map<String,String> t:targets){String tid=t.get("id");String tname=t.get("name");String tphoto=t.get("photo")==null?"":t.get("photo");if(tphoto.isEmpty()&&myId!=null&&myId.equals(tid))tphoto=getMyPhotoFromAllPlaces();Map<String,Object> gm=new HashMap<>();gm.put("senderId",myId);gm.put("senderName",myName);gm.put("senderPhoto",getSafePhotoForUpload());gm.put("senderCountry",myCountry);gm.put("senderLevel",myLevel);gm.put("msg","🎁 "+myName+" sent "+selectedGiftCount+"x "+selectedGiftName+" to "+tname);gm.put("time",System.currentTimeMillis());gm.put("giftName",selectedGiftName);gm.put("giftCount",selectedGiftCount);gm.put("giftPrice",selectedGiftPrice);gm.put("targetId",tid);gm.put("targetName",tname);activeRoomRef.child("chats").push().setValue(gm);Map<String,Object> eff=new HashMap<>();eff.put("senderId",myId);eff.put("senderName",myName);eff.put("senderPhoto",getSafePhotoForUpload());eff.put("targetId",tid);eff.put("targetName",tname);eff.put("targetPhoto",tphoto);eff.put("giftName",selectedGiftName);eff.put("giftCount",selectedGiftCount);eff.put("giftPrice",selectedGiftPrice);eff.put("time",System.currentTimeMillis());activeRoomRef.child("gift_effects").push().setValue(eff);final String fPhoto=tphoto;activeRoomRef.child("ranking").child("daily").child(tid).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot rs){long prev=0;try{if(rs.child("coins").getValue()!=null)prev=Long.parseLong(String.valueOf(rs.child("coins").getValue()));}catch(Exception ignored){}String oldPh=rs.child("photo").getValue(String.class);String finalPh=(fPhoto!=null&&!fPhoto.isEmpty())?fPhoto:(oldPh==null?"":oldPh);Map<String,Object> ru=new HashMap<>();ru.put("coins",prev+coinsPerTarget);ru.put("name",tname);ru.put("photo",finalPh);activeRoomRef.child("ranking").child("daily").child(tid).updateChildren(ru);}@Override public void onCancelled(@NonNull DatabaseError e){}});if(myId!=null&&myId.equals(tid))continue;resolveUserKeyByProfileId(tid,recvKey->{if(recvKey==null||recvKey.isEmpty())return;DatabaseReference rr=FirebaseDatabase.getInstance().getReference("users").child(recvKey);rr.addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot rs){long recvWallet=readWalletFromSnap(rs);long exchange=(coinsPerTarget*30)/100;long newRecvWallet=recvWallet+exchange;long curRecv=getLongVal(rs,"receiving");long curTotalRecv=getLongVal(rs,"totalReceiving");long curTarget=getLongVal(rs,"targetCoins");long curTargetTotal=getLongVal(rs,"totalTargetCoins");long newTotalRecv=curTotalRecv+coinsPerTarget;if(newTotalRecv==coinsPerTarget&&curTotalRecv==0)newTotalRecv=curRecv+coinsPerTarget;int charm=LevelUtils.calculateCharmLevel(newTotalRecv);Map<String,Object> ru=new HashMap<>();ru.put("coins",newRecvWallet);ru.put("coinBalance",newRecvWallet);ru.put("walletCoins",newRecvWallet);ru.put("sendingCoins",newRecvWallet);ru.put("receiving",curRecv+coinsPerTarget);ru.put("totalReceiving",newTotalRecv);ru.put("targetCoins",curTarget+coinsPerTarget);ru.put("totalTargetCoins",curTargetTotal+coinsPerTarget);ru.put("charmLevel",charm);rr.updateChildren(ru);}@Override public void onCancelled(@NonNull DatabaseError e){}});});}Toast.makeText(VoiceRoomActivity.this,"Gift "+selectedGiftName+" x"+selectedGiftCount+" sent to "+targets.size()+" user(s) 🎁",Toast.LENGTH_SHORT).show();if(d!=null)d.dismiss();}@Override public void onCancelled(@NonNull DatabaseError e){Toast.makeText(VoiceRoomActivity.this,"Wallet error - Try again",Toast.LENGTH_SHORT).show();}});});}
