private void openRoomHeaderPopup(){BottomSheetDialog d=new BottomSheetDialog(this);View v=LayoutInflater.from(this).inflate(R.layout.dialog_user_profile,null);d.setContentView(v);if(d.getWindow()!=null){d.getWindow().setBackgroundDrawableResource(android.R.color.transparent);d.getWindow().setLayout(android.view.ViewGroup.LayoutParams.MATCH_PARENT,android.view.ViewGroup.LayoutParams.WRAP_CONTENT);}ImageView ivProfile=v.findViewById(R.id.imgUserProfile);ImageView ivFrame=v.findViewById(R.id.imgUserFrame);TextView tvName=v.findViewById(R.id.txtUserName);TextView tvVip=v.findViewById(R.id.txtUserVipBadge);View layoutAgency=v.findViewById(R.id.layoutUserAgency);TextView tvAgency=v.findViewById(R.id.txtUserAgency);TextView tvGroup=v.findViewById(R.id.txtGroupName);TextView tvId=v.findViewById(R.id.txtUserId);TextView tvLevel=v.findViewById(R.id.txtUserLevel);TextView tvOwner=v.findViewById(R.id.txtRoomOwner);TextView tvLang=v.findViewById(R.id.txtHeaderLanguage);TextView tvCountry=v.findViewById(R.id.txtHeaderCountry);TextView tvTag=v.findViewById(R.id.txtHeaderTag);View rewardBanner=v.findViewById(R.id.layoutRewardBanner);RecyclerView rvMembers=v.findViewById(R.id.rvHeaderMembersList);TextView tvMembersCount=v.findViewById(R.id.txtMembersCount);View btnFollow=v.findViewById(R.id.btnFollow);if(btnFollow!=null)btnFollow.setVisibility(View.GONE);TextView txtProfileTab=v.findViewById(R.id.txtProfileTab);TextView txtMembersTopTab=v.findViewById(R.id.txtMembersTopTab);View layoutHeaderInfo=v.findViewById(R.id.layoutHeaderInfo);View layoutMembersSection=v.findViewById(R.id.layoutMembersSection);TextView txtMembersTab=v.findViewById(R.id.txtMembersTab);TextView txtAdminTab=v.findViewById(R.id.txtAdminTab);if(layoutHeaderInfo!=null)layoutHeaderInfo.setVisibility(View.VISIBLE);if(rewardBanner!=null)rewardBanner.setVisibility(View.VISIBLE);if(layoutMembersSection!=null)layoutMembersSection.setVisibility(View.VISIBLE);if(txtProfileTab!=null&&txtMembersTopTab!=null){txtProfileTab.setOnClickListener(x->{txtProfileTab.setTextColor(0xFF000000);txtProfileTab.setTypeface(null,android.graphics.Typeface.BOLD);txtMembersTopTab.setTextColor(0xFF999999);txtMembersTopTab.setTypeface(null,android.graphics.Typeface.NORMAL);if(layoutHeaderInfo!=null)layoutHeaderInfo.setVisibility(View.VISIBLE);if(rewardBanner!=null)rewardBanner.setVisibility(View.VISIBLE);});txtMembersTopTab.setOnClickListener(x->{txtMembersTopTab.setTextColor(0xFF000000);txtMembersTopTab.setTypeface(null,android.graphics.Typeface.BOLD);txtProfileTab.setTextColor(0xFF999999);txtProfileTab.setTypeface(null,android.graphics.Typeface.NORMAL);if(layoutHeaderInfo!=null)layoutHeaderInfo.setVisibility(View.GONE);if(rewardBanner!=null)rewardBanner.setVisibility(View.GONE);if(layoutMembersSection!=null)layoutMembersSection.setVisibility(View.VISIBLE);});}if(txtMembersTab!=null&&txtAdminTab!=null){txtMembersTab.setOnClickListener(x->{txtMembersTab.setTextColor(0xFF000000);txtMembersTab.setTypeface(null,android.graphics.Typeface.BOLD);txtAdminTab.setTextColor(0xFF666666);txtAdminTab.setTypeface(null,android.graphics.Typeface.NORMAL);});txtAdminTab.setOnClickListener(x->{txtAdminTab.setTextColor(0xFF000000);txtAdminTab.setTypeface(null,android.graphics.Typeface.BOLD);txtMembersTab.setTextColor(0xFF666666);txtMembersTab.setTypeface(null,android.graphics.Typeface.NORMAL);});}if(tvName!=null)tvName.setText(roomTitleText!=null?roomTitleText.getText().toString():"Room");if(tvGroup!=null)tvGroup.setText(roomTitleText!=null?roomTitleText.getText().toString():"");if(tvId!=null)tvId.setText("ID: "+roomOwnerId+" 📋");if(tvLevel!=null){int lv=1;try{lv=Integer.parseInt(myLevel);}catch(Exception e){lv=1;}tvLevel.setText("⭐ Level "+lv+" • "+LevelUtils.getLevelTitle(lv));GradientDrawable bg=new GradientDrawable();bg.setColors(LevelUtils.getLevelColors(lv));bg.setOrientation(GradientDrawable.Orientation.LEFT_RIGHT);bg.setCornerRadius(24);tvLevel.setBackground(bg);}if(tvOwner!=null)tvOwner.setText("Owner (ID:"+roomOwnerId+")");if(tvLang!=null)tvLang.setText(prefs.getString("USER_LANGUAGE","English"));if(tvCountry!=null)tvCountry.setText(myCountry);if(tvTag!=null)tvTag.setText(selectedLabel);if(ivProfile!=null)loadRoomPhotoInto(ivProfile);fetchVipForUser(roomOwnerId,vip->{if(vip>=1&&vip<=8){if(tvVip!=null){tvVip.setVisibility(View.VISIBLE);tvVip.setText(getVipEmoji(vip)+" VIP "+vip+" • "+getVipName(vip));}if(ivFrame!=null){ivFrame.setVisibility(View.VISIBLE);ivFrame.setBackgroundResource(android.R.drawable.dialog_holo_light_frame);}}else{if(tvVip!=null)tvVip.setVisibility(View.GONE);if(ivFrame!=null)ivFrame.setVisibility(View.GONE);}});resolveUserKeyByProfileId(roomOwnerId,key->{if(key==null||key.isEmpty())return;FirebaseDatabase.getInstance().getReference("users").child(key).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot ds){boolean isAgencyUser=ds.child("isAgency").getValue()!=null&&Boolean.TRUE.equals(ds.child("isAgency").getValue(Boolean.class));String agencyStatus=ds.child("agencyStatus").getValue()==null?"":String.valueOf(ds.child("agencyStatus").getValue());if(isAgencyUser&&!"blocked".equalsIgnoreCase(agencyStatus)&&!"rejected".equalsIgnoreCase(agencyStatus)){if(layoutAgency!=null&&tvAgency!=null){layoutAgency.setVisibility(View.VISIBLE);tvAgency.setText("AGENCY");tvAgency.setTextColor(0xFFFFFFFF);}}else{if(layoutAgency!=null)layoutAgency.setVisibility(View.GONE);}}@Override public void onCancelled(@NonNull DatabaseError e){}});});if(tvId!=null)tvId.setOnClickListener(x->{ClipboardManager cm=(ClipboardManager)getSystemService(Context.CLIPBOARD_SERVICE);if(cm!=null)cm.setPrimaryClip(ClipData.newPlainText("Room ID",roomOwnerId));Toast.makeText(this,"ID Copied",Toast.LENGTH_SHORT).show();});if(rewardBanner!=null)rewardBanner.setOnClickListener(x->openRewardEvent());if(rvMembers!=null){rvMembers.setLayoutManager(new LinearLayoutManager(this));List<Map<String,String>> members=new ArrayList<>();RecyclerView.Adapter adapter=new RecyclerView.Adapter<RecyclerView.ViewHolder>(){@NonNull @Override public RecyclerView.ViewHolder onCreateViewHolder(@NonNull android.view.ViewGroup p,int t){View item=LayoutInflater.from(p.getContext()).inflate(R.layout.item_user,p,false);return new RecyclerView.ViewHolder(item){};}@Override public void onBindViewHolder(@NonNull RecyclerView.ViewHolder h,int pos){Map<String,String> u=members.get(pos);ImageView iv=h.itemView.findViewById(R.id.imgChatPhoto);TextView tvH=h.itemView.findViewById(R.id.userName);TextView tvM=h.itemView.findViewById(R.id.tvChatMsg);loadPhotoInto(iv,u.get("photo"));if(tvH!=null)tvH.setText(u.get("name")+"  Lv."+u.get("level"));if(tvM!=null)tvM.setText("ID: "+u.get("id")+"  "+u.get("role"));}@Override public int getItemCount(){return members.size();}};rvMembers.setAdapter(adapter);activeRoomRef.child("online_users").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){members.clear();List<Map<String,String>> temp=new ArrayList<>();for(DataSnapshot c:snap.getChildren()){Map<String,String> m=new HashMap<>();m.put("name",c.child("name").getValue(String.class)==null?"User":c.child("name").getValue(String.class));String ph=c.child("photo").getValue(String.class);if(ph==null||ph.isEmpty())ph=c.child("photoUrl").getValue(String.class);m.put("photo",ph==null?"":ph);Object lvl=c.child("level").getValue();m.put("level",lvl==null?"1":String.valueOf(lvl));m.put("id",c.getKey());m.put("role","Member");temp.add(m);}for(Map<String,String> m:temp)if(m.get("id").equals(roomOwnerId)){m.put("role","Owner");members.add(m);}activeRoomRef.child("admins").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot aSnap){for(Map<String,String> m:temp){if(!m.get("id").equals(roomOwnerId)&&aSnap.hasChild(m.get("id"))){m.put("role","Admin");members.add(m);}}for(Map<String,String> m:temp){if(!m.get("id").equals(roomOwnerId)&&!aSnap.hasChild(m.get("id")))members.add(m);}if(tvMembersCount!=null)tvMembersCount.setText("Members: "+members.size()+"/1000    Admin: "+aSnap.getChildrenCount()+"/20");adapter.notifyDataSetChanged();}@Override public void onCancelled(@NonNull DatabaseError e){}});}@Override public void onCancelled(@NonNull DatabaseError e){}});}d.show();}
