private void openRanking(){BottomSheetDialog d=new BottomSheetDialog(this);View v=LayoutInflater.from(this).inflate(R.layout.dialog_room_ranking,null);d.setContentView(v);android.widget.LinearLayout container=v.findViewById(R.id.rankingListContainer);Button bDaily=v.findViewById(R.id.btnTabDaily);Button bWeekly=v.findViewById(R.id.btnTabWeekly);Button bMonthly=v.findViewById(R.id.btnTabMonthly);View btnClose=v.findViewById(R.id.btnCloseRanking);if(btnClose!=null)btnClose.setOnClickListener(x->d.dismiss());Runnable load=()->{if(bDaily!=null){bDaily.setBackgroundTintList(android.content.res.ColorStateList.valueOf(rankingTab.equals("daily")?0xFFFFD700:0xFF2A1B4E));bDaily.setTextColor(rankingTab.equals("daily")?0xFF000000:0xFFFFFFFF);}if(bWeekly!=null){bWeekly.setBackgroundTintList(android.content.res.ColorStateList.valueOf(rankingTab.equals("weekly")?0xFFFFD700:0xFF2A1B4E));bWeekly.setTextColor(rankingTab.equals("weekly")?0xFF000000:0xFFFFFFFF);}if(bMonthly!=null){bMonthly.setBackgroundTintList(android.content.res.ColorStateList.valueOf(rankingTab.equals("monthly")?0xFFFFD700:0xFF2A1B4E));bMonthly.setTextColor(rankingTab.equals("monthly")?0xFF000000:0xFFFFFFFF);}activeRoomRef.child("ranking").child(rankingTab).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){if(container!=null)container.removeAllViews();List<DataSnapshot> list=new ArrayList<>();for(DataSnapshot c:snap.getChildren())list.add(c);list.sort((a,b)->Long.compare(b.child("coins").getValue(Long.class)==null?0:b.child("coins").getValue(Long.class),a.child("coins").getValue(Long.class)==null?0:a.child("coins").getValue(Long.class)));for(int i=0;i<Math.min(3,list.size());i++){DataSnapshot c=list.get(i);String n=c.child("name").getValue(String.class);Long co=c.child("coins").getValue(Long.class);String name=n==null?"User":n;long coins=co==null?0:co;String ph=c.child("photo").getValue(String.class);String uid=c.getKey();if(ph==null)ph="";final String fPh=ph;final String fUid=uid;final String fName=name;if(i==0){TextView tn=v.findViewById(R.id.txtTop1Name);TextView tc=v.findViewById(R.id.txtTop1Coins);ImageView iv=v.findViewById(R.id.imgTop1Photo);if(tn!=null)tn.setText(name);if(tc!=null)tc.setText(coins+" 🪙");if(fPh!=null&&!fPh.isEmpty())loadPhotoInto(iv,fPh);else if(fUid!=null)activeRoomRef.child("online_users").child(fUid).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot os){String op=os.child("photo").getValue(String.class);if(op==null||op.isEmpty())op=os.child("photoUrl").getValue(String.class);if(op!=null&&!op.isEmpty())loadPhotoInto(iv,op);}@Override public void onCancelled(@NonNull DatabaseError e){}});}if(i==1){TextView tn=v.findViewById(R.id.txtTop2Name);TextView tc=v.findViewById(R.id.txtTop2Coins);ImageView iv=v.findViewById(R.id.imgTop2Photo);if(tn!=null)tn.setText(name);if(tc!=null)tc.setText(coins+" 🪙");if(fPh!=null&&!fPh.isEmpty())loadPhotoInto(iv,fPh);else if(fUid!=null)activeRoomRef.child("online_users").child(fUid).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot os){String op=os.child("photo").getValue(String.class);if(op==null||op.isEmpty())op=os.child("photoUrl").getValue(String.class);if(op!=null&&!op.isEmpty())loadPhotoInto(iv,op);}@Override public void onCancelled(@NonNull DatabaseError e){}});}if(i==2){TextView tn=v.findViewById(R.id.txtTop3Name);TextView tc=v.findViewById(R.id.txtTop3Coins);ImageView iv=v.findViewById(R.id.imgTop3Photo);if(tn!=null)tn.setText(name);if(tc!=null)tc.setText(coins+" 🪙");if(fPh!=null&&!fPh.isEmpty())loadPhotoInto(iv,fPh);else if(fUid!=null)activeRoomRef.child("online_users").child(fUid).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot os){String op=os.child("photo").getValue(String.class);if(op==null||op.isEmpty())op=os.child("photoUrl").getValue(String.class);if(op!=null&&!op.isEmpty())loadPhotoInto(iv,op);}@Override public void onCancelled(@NonNull DatabaseError e){}});}}for(int i=3;i<list.size();i++){DataSnapshot c=list.get(i);View row;try{row=LayoutInflater.from(VoiceRoomActivity.this).inflate(R.layout.item_ranking,container,false);}catch(Exception e){row=new TextView(VoiceRoomActivity.this);((TextView)row).setText((i+1)+". "+c.child("name").getValue(String.class)+" - "+(c.child("coins").getValue(Long.class)==null?0:c.child("coins").getValue(Long.class))+" 🪙");((TextView)row).setTextColor(0xFFFFFFFF);container.addView(row);continue;}TextView tvRank=row.findViewById(R.id.txtRankNumber);TextView tvName=row.findViewById(R.id.txtRankName);TextView tvCoin=row.findViewById(R.id.txtRankCoins);ImageView iv=row.findViewById(R.id.imgRankPhoto);if(tvRank!=null)tvRank.setText(String.valueOf(i+1));if(tvName!=null)tvName.setText(c.child("name").getValue(String.class));if(tvCoin!=null)tvCoin.setText((c.child("coins").getValue(Long.class)==null?0:c.child("coins").getValue(Long.class))+" 🪙");String ph=c.child("photo").getValue(String.class);loadPhotoInto(iv,ph==null?"":ph);container.addView(row);}}@Override public void onCancelled(@NonNull DatabaseError e){}});};if(bDaily!=null)bDaily.setOnClickListener(x->{rankingTab="daily";load.run();});if(bWeekly!=null)bWeekly.setOnClickListener(x->{rankingTab="weekly";load.run();});if(bMonthly!=null)bMonthly.setOnClickListener(x->{rankingTab="monthly";load.run();});load.run();d.show();}
private void syncMyPhotoFromFirebase(){resolveUserKeyByProfileId(myId,key->{if(key==null||key.isEmpty())return;FirebaseDatabase.getInstance().getReference("users").child(key).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){DataSnapshot ds=snap;String p=null;if(ds.child("photoUrl").getValue()!=null)p=String.valueOf(ds.child("photoUrl").getValue());if((p==null||p.isEmpty())&&ds.child("photo").getValue()!=null)p=String.valueOf(ds.child("photo").getValue());if((p==null||p.isEmpty())&&ds.child("photoBase64").getValue()!=null)p=String.valueOf(ds.child("photoBase64").getValue());if(p!=null&&!p.isEmpty()&&!p.equals("null")){myPhoto=p;prefs.edit().putString("USER_PHOTO",p).putString("PROFILE_PHOTO",p).apply();markMeOnline();}String hw=null;if(ds.child("headwearImage").getValue()!=null)hw=String.valueOf(ds.child("headwearImage").getValue());if((hw==null||hw.isEmpty())&&ds.child("headwearUrl").getValue()!=null)hw=String.valueOf(ds.child("headwearUrl").getValue());if((hw==null||hw.isEmpty())&&ds.child("headwearBase64").getValue()!=null)hw=String.valueOf(ds.child("headwearBase64").getValue());if((hw==null||hw.isEmpty())&&ds.child("HEADWEAR_IMAGE").getValue()!=null)hw=String.valueOf(ds.child("HEADWEAR_IMAGE").getValue());if(hw!=null&&!hw.isEmpty()){prefs.edit().putString("HEADWEAR_IMAGE",hw).apply();if(roomHeaderHeadwearImg!=null)loadHeadwearInto(roomHeaderHeadwearImg,hw);}}@Override public void onCancelled(@NonNull DatabaseError e){}});});}
private void restoreHeaderCache(){try{if(prefs==null||roomOwnerId==null)return;String k="HEADER_"+roomOwnerId;String n=prefs.getString(k+"_NAME","");String ph=prefs.getString(k+"_PHOTO","");String an=prefs.getString(k+"_ANN","");String th=prefs.getString(k+"_THEME","");String lb=prefs.getString(k+"_LABEL","");if(n!=null&&!n.isEmpty()){if(tvRoomName!=null)tvRoomName.setText(n);if(roomTitleText!=null)roomTitleText.setText(n);}if(ph!=null&&!ph.isEmpty()&&!ph.equals("null")&&!ph.startsWith("content://"))currentRoomPhotoUrl=ph;if(an!=null)currentAnnouncement=an;if(lb!=null&&!lb.isEmpty())selectedLabel=lb;if(th!=null&&!th.isEmpty())selectedTheme=th;if(roomHeaderProfileImg!=null)loadRoomPhotoInto(roomHeaderProfileImg);if(!selectedTheme.isEmpty())applyTheme(selectedTheme);if(!currentAnnouncement.isEmpty()){TextView notice=findViewById(R.id.roomNoticeBarText);if(notice!=null){notice.setVisibility(View.VISIBLE);notice.setText(currentAnnouncement);}}}catch(Exception ignored){}}
private void saveHeaderCache(String n,String ph,String an,String th,String lb){try{if(prefs==null||roomOwnerId==null)return;String k="HEADER_"+roomOwnerId;prefs.edit().putString(k+"_NAME",n==null?"":n).putString(k+"_PHOTO",ph==null?"":ph).putString(k+"_ANN",an==null?"":an).putString(k+"_THEME",th==null?"":th).putString(k+"_LABEL",lb==null?"":lb).apply();}catch(Exception ignored){}}
private void applyHeaderFromSnap(DataSnapshot snap){String rName=snap.child("roomName").getValue(String.class);String rPhoto=snap.child("roomPhoto").getValue(String.class);if(rPhoto==null||rPhoto.isEmpty())rPhoto=snap.child("roomOwnerImage").getValue(String.class);String rAnnounce=snap.child("announcement").getValue(String.class);if(rAnnounce==null||rAnnounce.isEmpty())rAnnounce=snap.child("roomBio").getValue(String.class);String rTheme=snap.child("theme").getValue(String.class);String rLabel=snap.child("roomLabel").getValue(String.class);if(rName!=null&&!rName.isEmpty()){if(tvRoomName!=null)tvRoomName.setText(rName);if(roomTitleText!=null)roomTitleText.setText(rName);}if(rPhoto!=null&&!rPhoto.isEmpty()&&!rPhoto.equals("null")&&!rPhoto.startsWith("content://")&&!rPhoto.startsWith("file://"))currentRoomPhotoUrl=rPhoto;if(roomHeaderProfileImg!=null)loadRoomPhotoInto(roomHeaderProfileImg);if(rAnnounce!=null){currentAnnouncement=rAnnounce;if(!rAnnounce.isEmpty()){TextView notice=findViewById(R.id.roomNoticeBarText);if(notice!=null){notice.setVisibility(View.VISIBLE);notice.setText(rAnnounce);}}}if(rLabel!=null&&!rLabel.isEmpty())selectedLabel=rLabel;if(rTheme!=null&&!rTheme.isEmpty()){selectedTheme=rTheme;applyTheme(selectedTheme);}String fName=roomTitleText!=null&&roomTitleText.getText()!=null?roomTitleText.getText().toString():"";saveHeaderCache(fName,currentRoomPhotoUrl,currentAnnouncement,selectedTheme,selectedLabel);}
@Override protected void onCreate(Bundle savedInstanceState){super.onCreate(savedInstanceState);setContentView(R.layout.activity_voice_room);joinTime=System.currentTimeMillis();prefs=getSharedPreferences("SR_USER",MODE_PRIVATE);myId=prefs.getString("PROFILE_ID","");if(myId==null||myId.isEmpty())myId=prefs.getString("MY_9_DIGIT_ID","");if(myId==null||myId.isEmpty())myId=prefs.getString("MY_ID","");myName=prefs.getString("USER_NAME","User");myGender=prefs.getString("USER_GENDER","");myCountry=prefs.getString("USER_COUNTRY","Bangladesh");myPhoto=getMyPhotoFromAllPlaces();myLevel=prefs.getString("USER_LEVEL","1");if(myLevel==null||myLevel.equals("0"))myLevel="1";if(myId==null||myId.isEmpty()){Toast.makeText(this,"ID not found, Login again",Toast.LENGTH_LONG).show();finish();return;}String intentRoomId=getIntent().getStringExtra("ROOM_ID");String intentOwnerId=getIntent().getStringExtra("ROOM_OWNER_ID");if(intentRoomId!=null&&!intentRoomId.isEmpty())roomId=intentRoomId;else roomId=myId;if(intentOwnerId!=null&&!intentOwnerId.isEmpty())roomOwnerId=intentOwnerId;else roomOwnerId=roomId;activeRoomRef=FirebaseDatabase.getInstance().getReference("active_rooms").child(roomOwnerId);roomMetaRef=FirebaseDatabase.getInstance().getReference("rooms").child("room_"+roomOwnerId).child("meta");tvRoomId=findViewById(R.id.tvRoomId);tvRoomName=findViewById(R.id.tvRoomName);tvMyIdInRoom=findViewById(R.id.tvMyIdInRoom);btnRoomSet=findViewById(R.id.btnRoomSet);btnRoomEdit=findViewById(R.id.btnRoomEdit);layoutOwnerTools=findViewById(R.id.layoutOwnerTools);rvOnline=findViewById(R.id.rvOnline);roomTitleText=findViewById(R.id.roomTitleText);roomInfoText=findViewById(R.id.roomInfoText);roomHeaderProfileImg=findViewById(R.id.roomHeaderProfileImg);roomHeaderHeadwearImg=findViewById(R.id.roomHeaderHeadwearImg);chatListContainer=findViewById(R.id.chatListContainer);imgRoomBackground=findViewById(R.id.imgRoomBackground);restoreHeaderCache();if(rvOnline!=null)rvOnline.setLayoutManager(new LinearLayoutManager(this));if(roomHeaderProfileImg!=null)loadRoomPhotoInto(roomHeaderProfileImg);if(roomHeaderHeadwearImg!=null)loadHeadwearInto(roomHeaderHeadwearImg,getMyHeadwearFromAllPlaces());if(tvRoomId!=null)tvRoomId.setText("Room ID: "+roomId);if(roomInfoText!=null)roomInfoText.setText("ID: "+roomId);if(tvMyIdInRoom!=null)tvMyIdInRoom.setText("My ID: "+myId+" | "+myName);if(layoutOwnerTools!=null)layoutOwnerTools.setVisibility(View.GONE);if(btnRoomSet!=null)btnRoomSet.setVisibility(View.GONE);if(btnRoomEdit!=null)btnRoomEdit.setVisibility(View.GONE);getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){@Override public void handleOnBackPressed(){showPowerMenu();}});startWalletListener();checkMyRole();loadRoomInfo();syncMyPhotoFromFirebase();markMeOnline();setupSeats();showVipEntryEffect(myId,myName);listenEntryEffect();if(roomHeaderProfileImg!=null)roomHeaderProfileImg.setOnClickListener(v->openRoomHeaderPopup());if(roomTitleText!=null)roomTitleText.setOnClickListener(v->openRoomHeaderPopup());if(roomInfoText!=null)roomInfoText.setOnClickListener(v->openRoomHeaderPopup());View btnRanking=findViewById(R.id.btnInRoomRanking);if(btnRanking!=null)btnRanking.setOnClickListener(v->openRanking());setupRankingBanner();listenRankingTotal();View btnOpenChat=findViewById(R.id.btnOpenChat);if(btnOpenChat!=null)btnOpenChat.setOnClickListener(v->openChatInput());View btnOnlineList=findViewById(R.id.btnOnlineList);if(btnOnlineList!=null)btnOnlineList.setOnClickListener(v->openOnlineList());View tvOnlineCount=findViewById(R.id.textOnlineCount);if(tvOnlineCount!=null)tvOnlineCount.setOnClickListener(v->openOnlineList());View btnRoomTools=findViewById(R.id.btnRoomTools);if(btnRoomTools!=null)btnRoomTools.setOnClickListener(v->openPremiumSettings());View btnGame=findViewById(R.id.btnGame);if(btnGame!=null)btnGame.setOnClickListener(v->openGameList());if(btnRoomSet!=null)btnRoomSet.setOnClickListener(v->openRoomSetDialog());ImageButton btnPower=findViewById(R.id.btnPower);if(btnPower!=null)btnPower.setOnClickListener(v->showPowerMenu());View btnGiftBottom=findViewById(R.id.btnGiftBox);if(btnGiftBottom!=null)btnGiftBottom.setOnClickListener(v->openBottomGift());listenChatRealtime();listenGiftEffects();listenOnlineCount();}
private String getFlag(String country){if(country==null)return "🌍";String c=country.toLowerCase();if(c.contains("bangladesh"))return "🇧🇩";if(c.contains("india"))return "🇮🇳";if(c.contains("pakistan"))return "🇵🇰";if(c.contains("nepal"))return "🇳🇵";if(c.contains("sri lanka"))return "🇱🇰";if(c.contains("usa")||c.contains("america"))return "🇺🇸";if(c.contains("uk")||c.contains("england"))return "🇬🇧";if(c.contains("saudi"))return "🇸🇦";if(c.contains("uae")||c.contains("emirates"))return "🇦🇪";if(c.contains("qatar"))return "🇶🇦";if(c.contains("kuwait"))return "🇰🇼";if(c.contains("malaysia"))return "🇲🇾";if(c.contains("indonesia"))return "🇮🇩";if(c.contains("philippines"))return "🇵🇭";if(c.contains("turkey"))return "🇹🇷";if(c.contains("canada"))return "🇨🇦";if(c.contains("australia"))return "🇦🇺";return "🌍";}
private String getCountryShort(String c){if(c==null||c.isEmpty())return "";String cl=c.trim().toLowerCase();if(cl.contains("bangladesh")||cl.equals("bd"))return "🇧🇩 BD";if(cl.contains("india"))return "🇮🇳 IN";if(cl.contains("pakistan"))return "🇵🇰 PK";if(cl.contains("nepal"))return "🇳🇵 NP";if(cl.contains("sri lanka")||cl.contains("srilanka"))return "🇱🇰 LK";if(cl.contains("united arab")||cl.contains("uae")||cl.contains("dubai"))return "🇦🇪 AE";if(cl.contains("saudi"))return "🇸🇦 SA";if(cl.contains("qatar"))return "🇶🇦 QA";if(cl.contains("kuwait"))return "🇰🇼 KW";if(cl.contains("oman"))return "🇴🇲 OM";if(cl.contains("bahrain"))return "🇧🇭 BH";if(cl.contains("united states")||cl.contains("america")||cl.equals("us"))return "🇺🇸 US";if(cl.contains("canada"))return "🇨🇦 CA";if(cl.contains("united kingdom")||cl.contains("uk")||cl.contains("england"))return "🇬🇧 UK";if(cl.contains("turkey"))return "🇹🇷 TR";if(cl.contains("malaysia"))return "🇲🇾 MY";if(cl.contains("indonesia"))return "🇮🇩 ID";if(cl.contains("philippines"))return "🇵🇭 PH";if(cl.contains("australia"))return "🇦🇺 AU";if(cl.contains("egypt"))return "🇪🇬 EG";return "🌍 "+c.trim();}
private String getGenderIconPremium(String g){if(g==null)return "";String gl=g.trim().toLowerCase();if(gl.contains("female")||gl.contains("girl")||gl.contains("woman")||gl.equals("f"))return "♀️";if(gl.contains("male")||gl.contains("boy")||gl.contains("man")||gl.equals("m"))return "♂️";return "";}
private void markMeOnline(){String safePhoto=getSafePhotoForUpload();if(safePhoto.isEmpty()){Map<String,Object> m2=new HashMap<>();m2.put("name",myName);m2.put("country",myCountry);m2.put("level",myLevel);m2.put("id",myId);activeRoomRef.child("online_users").child(myId).updateChildren(m2);activeRoomRef.child("online_users").child(myId).onDisconnect().removeValue();return;}myPhoto=safePhoto;Map<String,Object> m=new HashMap<>();m.put("name",myName);m.put("photo",myPhoto);m.put("photoUrl",myPhoto);m.put("country",myCountry);m.put("level",myLevel);m.put("id",myId);activeRoomRef.child("online_users").child(myId).setValue(m);activeRoomRef.child("online_users").child(myId).onDisconnect().removeValue();}
private void listenOnlineCount(){activeRoomRef.child("online_users").addValueEventListener(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){TextView tvC=findViewById(R.id.textOnlineCount);if(tvC!=null)tvC.setText(String.valueOf(snap.getChildrenCount()));}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void openChatInput(){BottomSheetDialog d=new BottomSheetDialog(this);View v=LayoutInflater.from(this).inflate(R.layout.dialog_room_chat,null);d.setContentView(v);EditText et=v.findViewById(R.id.etChatInput);et.requestFocus();if(d.getWindow()!=null)d.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);d.setOnShowListener(dialog->{et.requestFocus();android.view.inputmethod.InputMethodManager imm=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(imm!=null)imm.showSoftInput(et,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});v.findViewById(R.id.btnSendChat).setOnClickListener(x->{String msg=et.getText().toString().trim();if(msg.isEmpty())return;Map<String,Object> m=new HashMap<>();m.put("senderId",myId);m.put("senderName",myName);m.put("senderPhoto",getSafePhotoForUpload());m.put("senderCountry",myCountry);m.put("senderLevel",myLevel);m.put("msg",msg);m.put("time",System.currentTimeMillis());activeRoomRef.child("chats").push().setValue(m);d.dismiss();});d.show();}
private void listenChatRealtime(){if(chatListContainer!=null)chatListContainer.removeAllViews();if(chatListener!=null&&chatQuery!=null){try{chatQuery.removeEventListener(chatListener);}catch(Exception e){}}chatQuery=activeRoomRef.child("chats").orderByChild("time").startAt(joinTime+1);chatListener=new ChildEventListener(){@Override public void onChildAdded(@NonNull DataSnapshot snap,String p){if(snap==null||snap.exists()==false)return;Long t=snap.child("time").getValue(Long.class);if(t==null||t<=joinTime)return;String name=snap.child("senderName").getValue(String.class);String photo=snap.child("senderPhoto").getValue(String.class);String country=snap.child("senderCountry").getValue(String.class);String level=snap.child("senderLevel").getValue(String.class);String msg=snap.child("msg").getValue(String.class);if(name==null)name="User";if(msg==null)msg="";if(country==null)country="";if(level==null)level="1";addChatToScreen(name,photo,country,level,msg);}@Override public void onChildChanged(@NonNull DataSnapshot s,String p){}@Override public void onChildRemoved(@NonNull DataSnapshot s){if(chatListContainer!=null)chatListContainer.removeAllViews();}@Override public void onChildMoved(@NonNull DataSnapshot s,String p){}@Override public void onCancelled(@NonNull DatabaseError e){}};chatQuery.addChildEventListener(chatListener);}
private void addChatToScreen(String name,String photo,String country,String level,String msg){if(chatListContainer==null)return;View v=LayoutInflater.from(this).inflate(R.layout.item_chat,chatListContainer,false);ImageView iv=v.findViewById(R.id.imgChatPhoto);TextView tvH=v.findViewById(R.id.tvChatHeader);TextView tvM=v.findViewById(R.id.tvChatMsg);loadPhotoInto(iv,photo);tvH.setText(name+"  Lv."+level+"  "+getFlag(country));tvM.setText(msg);chatListContainer.addView(v);}
private void openOnlineList(){BottomSheetDialog d=new BottomSheetDialog(this);View v=LayoutInflater.from(this).inflate(R.layout.dialog_online_list,null);d.setContentView(v);RecyclerView rv=v.findViewById(R.id.rvOnlineList);rv.setLayoutManager(new LinearLayoutManager(this));List<Map<String,String>> list=new ArrayList<>();RecyclerView.Adapter adapter=new RecyclerView.Adapter<RecyclerView.ViewHolder>(){@NonNull @Override public RecyclerView.ViewHolder onCreateViewHolder(@NonNull android.view.ViewGroup p,int t){View item=LayoutInflater.from(p.getContext()).inflate(R.layout.item_user,p,false);return new RecyclerView.ViewHolder(item){};}@Override public void onBindViewHolder(@NonNull RecyclerView.ViewHolder h,int pos){Map<String,String> u=list.get(pos);ImageView iv=h.itemView.findViewById(R.id.imgChatPhoto);TextView tvH=h.itemView.findViewById(R.id.userName);TextView tvM=h.itemView.findViewById(R.id.tvChatMsg);loadPhotoInto(iv,u.get("photo"));tvH.setText(u.get("name")+"  Lv."+u.get("level")+"  "+getFlag(u.get("country")));tvM.setText("ID: "+u.get("id"));h.itemView.setOnClickListener(x->openMiniProfile(u.get("id"),u.get("name"),u.get("photo")));}@Override public int getItemCount(){return list.size();}};rv.setAdapter(adapter);activeRoomRef.child("online_users").addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){list.clear();for(DataSnapshot c:snap.getChildren()){Map<String,String> m=new HashMap<>();m.put("name",c.child("name").getValue(String.class)==null?"User":c.child("name").getValue(String.class));String ph=c.child("photo").getValue(String.class);if(ph==null||ph.isEmpty())ph=c.child("photoUrl").getValue(String.class);m.put("photo",ph==null?"":ph);m.put("country",c.child("country").getValue(String.class)==null?"":c.child("country").getValue(String.class));Object lvlObj=c.child("level").getValue();m.put("level",lvlObj==null?"1":String.valueOf(lvlObj));m.put("id",c.getKey());list.add(m);}adapter.notifyDataSetChanged();}@Override public void onCancelled(@NonNull DatabaseError e){}});v.findViewById(R.id.btnCloseOnline).setOnClickListener(x->d.dismiss());d.show();}
private void showPowerMenu(){String[] options={"Minimize","Exit Room"};new AlertDialog.Builder(this).setTitle("Room Options").setItems(options,(dialog,which)->{if(which==0){isExiting=false;finish();}else{isExiting=true;finishAffinity();}}).setNegativeButton("Cancel",null).show();}
private void checkMyRole(){amIOwner=myId.equals(roomOwnerId);activeRoomRef.child("admins").child(myId).addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){amIAdmin=snap.exists()&&Boolean.TRUE.equals(snap.getValue(Boolean.class));}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void loadRoomInfo(){roomMetaRef.addValueEventListener(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot snap){if(!snap.exists()){activeRoomRef.addListenerForSingleValueEvent(new ValueEventListener(){@Override public void onDataChange(@NonNull DataSnapshot aSnap){if(aSnap.exists())applyHeaderFromSnap(aSnap);}@Override public void onCancelled(@NonNull DatabaseError e){}});return;}applyHeaderFromSnap(snap);}@Override public void onCancelled(@NonNull DatabaseError e){}});}
private void openPremiumSettings(){BottomSheetDialog dialog=new BottomSheetDialog(this);View view=LayoutInflater.from(this).inflate(R.layout.dialog_room_tools,null);dialog.setContentView(view);view.findViewById(R.id.toolRoomSet).setOnClickListener(v->{dialog.dismiss();openRoomSetDialog();});view.findViewById(R.id.toolRoomEdit).setOnClickListener(v->{dialog.dismiss();openRoomSetDialog();});view.findViewById(R.id.toolClearChat).setOnClickListener(v->{dialog.dismiss();clearChat();});view.findViewById(R.id.toolLock).setOnClickListener(v->Toast.makeText(this,"Lock on - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolClearCharm).setOnClickListener(v->Toast.makeText(this,"Clear charm - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolChangeMic).setOnClickListener(v->Toast.makeText(this,"Change mic - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolDress).setOnClickListener(v->Toast.makeText(this,"Dress - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolLuckySound).setOnClickListener(v->Toast.makeText(this,"Lucky Sound - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolVoiceUser).setOnClickListener(v->Toast.makeText(this,"Voice User - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolKickRecord).setOnClickListener(v->Toast.makeText(this,"Kick out record - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolYoutube).setOnClickListener(v->Toast.makeText(this,"YouTube Co-watch - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolLuckyFloat).setOnClickListener(v->Toast.makeText(this,"Lucky Float - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolRoomPK).setOnClickListener(v->Toast.makeText(this,"Room PK - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.toolBroadcast).setOnClickListener(v->Toast.makeText(this,"Broadcast - Coming Soon",Toast.LENGTH_SHORT).show());view.findViewById(R.id.btnToolsClose).setOnClickListener(v->dialog.dismiss());dialog.show();}
private void clearChat(){if(chatListContainer!=null)chatListContainer.removeAllViews();activeRoomRef.child("chats").removeValue();Toast.makeText(this,"Chat Cleaned",Toast.LENGTH_SHORT).show();}
private void openRoomSetDialog(){if(!amIOwner&&!amIAdmin){Toast.makeText(this,"Only Room Owner / Admin can change",Toast.LENGTH_SHORT).show();return;}pickedRoomPhotoUri=null;pickedRoomPhotoBase64=null;AlertDialog.Builder builder=new AlertDialog.Builder(this);View view=LayoutInflater.from(this).inflate(R.layout.dialog_room_set,null);builder.setView(view);AlertDialog dialog=builder.create();dialogRoomPhoto=view.findViewById(R.id.imgRoomPhoto);EditText etName=view.findViewById(R.id.etRoomName);EditText etAnnounce=view.findViewById(R.id.etRoomAnnouncement);TextView tvTheme=view.findViewById(R.id.tvSelectedTheme);if(roomTitleText!=null&&roomTitleText.getText()!=null&&roomTitleText.getText().length()>0)etName.setText(roomTitleText.getText().toString());else if(tvRoomName!=null)etName.setText(tvRoomName.getText().toString());if(etAnnounce!=null)etAnnounce.setText(currentAnnouncement==null?"":currentAnnouncement);if(dialogRoomPhoto!=null)loadRoomPhotoInto(dialogRoomPhoto);if(tvTheme!=null)tvTheme.setText("Theme: "+selectedTheme);if(dialogRoomPhoto!=null)dialogRoomPhoto.setOnClickListener(v->pickRoomPhoto.launch("image/*"));View rowTheme=view.findViewById(R.id.layoutRoomThemeRow);ImageView thumb=view.findViewById(R.id.imgSelectedThemeThumb);TextView tvNameCount=view.findViewById(R.id.tvRoomNameCount);TextView tvAnnCount=view.findViewById(R.id.tvRoomAnnounceCount);if(rowTheme!=null)rowTheme.setOnClickListener(v->openThemePicker(tvTheme,thumb));if(etName!=null&&tvNameCount!=null)etName.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){tvNameCount.setText(s.length()+"/20");}public void afterTextChanged(android.text.Editable s){}});if(etAnnounce!=null&&tvAnnCount!=null)etAnnounce.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){tvAnnCount.setText(s.length()+"/200");}public void afterTextChanged(android.text.Editable s){}});int[] labelIds={R.id.btnLabelFriends,R.id.btnLabelGame,R.id.btnLabelMusic,R.id.btnLabelChat};String[] labelNames={"Friends","Game","Music","Chat"};for(int i=0;i<labelIds.length;i++){Button b=view.findViewById(labelIds[i]);if(b==null)continue;final String ln=labelNames[i];final Button fb=b;if(ln.equals(selectedLabel))b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFFFFC107));b.setOnClickListener(v->{selectedLabel=ln;for(int j=0;j<labelIds.length;j++){Button bb=view.findViewById(labelIds[j]);if(bb!=null)bb.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFFE0E0E0));}fb.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFFFFC107));});}if(view.findViewById(R.id.btnThemeDefault)!=null)view.findViewById(R.id.btnThemeDefault).setOnClickListener(v->{selectedTheme="Default";if(tvTheme!=null)tvTheme.setText("Theme: Default");applyTheme(selectedTheme);});if(view.findViewById(R.id.btnThemeGold)!=null)view.findViewById(R.id.btnThemeGold).setOnClickListener(v->{selectedTheme="Gold";if(tvTheme!=null)tvTheme.setText("Theme: Gold");});if(view.findViewById(R.id.btnThemeNight)!=null)view.findViewById(R.id.btnThemeNight).setOnClickListener(v->{selectedTheme="Night";if(tvTheme!=null)tvTheme.setText("Theme: Night");});View btnSave=view.findViewById(R.id.btnSaveRoomSet);if(btnSave!=null)btnSave.setOnClickListener(v->{String newName=etName.getText().toString().trim();String newAnnounce=etAnnounce.getText().toString().trim();if(newName.isEmpty()){Toast.makeText(this,"Enter Room Name",Toast.LENGTH_SHORT).show();return;}String finalPhoto=currentRoomPhotoUrl;if(pickedRoomPhotoBase64!=null&&!pickedRoomPhotoBase64.isEmpty())finalPhoto=pickedRoomPhotoBase64;if(finalPhoto==null)finalPhoto="";Map<String,Object> map=new HashMap<>();map.put("roomName",newName);map.put("announcement",newAnnounce);map.put("theme",selectedTheme);map.put("roomLabel",selectedLabel);map.put("roomPhoto",finalPhoto);map.put("roomBio",newAnnounce);map.put("roomOwnerImage",finalPhoto);map.put("roomId",roomOwnerId);map.put("ownerId",roomOwnerId);map.put("roomOwnerId",roomOwnerId);roomMetaRef.updateChildren(map);Map<String,Object> activeMap=new HashMap<>();activeMap.put("roomName",newName);activeMap.put("roomPhoto",finalPhoto);activeMap.put("announcement",newAnnounce);activeMap.put("roomBio",newAnnounce);activeMap.put("theme",selectedTheme);activeMap.put("roomLabel",selectedLabel);activeMap.put("roomOwnerImage",finalPhoto);activeMap.put("roomOwnerId",roomOwnerId);activeMap.put("roomId",roomOwnerId);activeRoomRef.updateChildren(activeMap);currentRoomPhotoUrl=finalPhoto;currentAnnouncement=newAnnounce;saveHeaderCache(newName,finalPhoto,newAnnounce,selectedTheme,selectedLabel);if(tvRoomName!=null)tvRoomName.setText(newName);if(roomTitleText!=null)roomTitleText.setText(newName);if(roomHeaderProfileImg!=null)loadRoomPhotoInto(roomHeaderProfileImg);pickedRoomPhotoUri=null;pickedRoomPhotoBase64=null;Toast.makeText(this,"Room Saved",Toast.LENGTH_SHORT).show();dialog.dismiss();});View btnCancel=view.findViewById(R.id.btnCancelRoomSet);if(btnCancel!=null)btnCancel.setOnClickListener(v->dialog.dismiss());dialog.show();}
private void openGameList(){BottomSheetDialog d=new BottomSheetDialog(this);android.widget.LinearLayout layout=new android.widget.LinearLayout(this);layout.setOrientation(android.widget.LinearLayout.VERTICAL);layout.setPadding(40,40,40,40);layout.setBackgroundColor(0xFF1A1333);TextView title=new TextView(this);title.setText("🎮 Game Center");title.setTextSize(20);title.setTextColor(0xFFFFFFFF);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setGravity(android.view.Gravity.CENTER);layout.addView(title);TextView sub=new TextView(this);sub.setText("Room theke ber na hoye khelun");sub.setTextColor(0xFFAAAAAA);sub.setGravity(android.view.Gravity.CENTER);sub.setPadding(0,8,0,24);layout.addView(sub);Button btnFruit=new Button(this);btnFruit.setText("🍓 Fruit Party  •  LIVE");btnFruit.setTextSize(16);btnFruit.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFFFF4081));btnFruit.setTextColor(0xFFFFFFFF);btnFruit.setOnClickListener(v->{d.dismiss();try{android.content.Intent intent=new android.content.Intent(VoiceRoomActivity.this,FruitPartyActivity.class);intent.putExtra("ROOM_ID",roomId);intent.putExtra("ROOM_OWNER_ID",roomOwnerId);startActivity(intent);}catch(Exception e){Toast.makeText(this,"Fruit Party - Coming Soon, Activity add koro",Toast.LENGTH_SHORT).show();}});layout.addView(btnFruit);Button btnLudo=new Button(this);btnLudo.setText("🎲 Ludo  •  Coming Soon");btnLudo.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF2A1B4E));btnLudo.setTextColor(0xFFFFFFFF);btnLudo.setOnClickListener(v->Toast.makeText(this,"Ludo Coming Soon!",Toast.LENGTH_SHORT).show());layout.addView(btnLudo);Button btnWheel=new Button(this);btnWheel.setText("🎡 Lucky Wheel  •  Coming Soon");btnWheel.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF2A1B4E));btnWheel.setTextColor(0xFFFFFFFF);btnWheel.setOnClickListener(v->Toast.makeText(this,"Lucky Wheel Coming Soon!",Toast.LENGTH_SHORT).show());layout.addView(btnWheel);Button btnClose=new Button(this);btnClose.setText("Close");btnClose.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xFF444444));btnClose.setTextColor(0xFFFFFFFF);btnClose.setOnClickListener(v->d.dismiss());layout.addView(btnClose);d.setContentView(layout);d.show();}
